REPLACE['backend/app/backtest/emc/emc_v1_engine.py'] = ('af5e46f07f66311efc9d60557debd21c69f277a7fe4c26da39d91586d713790f', '# backend/app/backtest/emc/emc_v1_engine.py\n#\n# ── EMC_V1 ENGINE ── "Ember": EMA(9/21) cross on NIFTY SPOT arms an option,\n# the option\'s OWN EMA(9/21) alignment buys it. Pure module (no I/O).\n#\n# Fence: EMC_V1_20261011\n#\n# Decisions (the runner owns data access; everything that decides a trade\n# lives here so a future paper/live engine can re-run it — parity by\n# construction):\n#   E1  Bars: 1m resampled to `tf` minutes on the NSE session grid (buckets\n#       from 09:15, TradingView NSE parity). A bar\'s end minute is recorded.\n#   E2  EMA = Pine ta.ema: None until `period` values exist, the period-th\n#       value is the SMA seed, then alpha = 2/(period+1). SPOT EMAs are\n#       continuous across sessions (the chart does not reset at 09:15).\n#   E3  Spot cross on a CLOSED spot bar, Pine ta.crossover/ta.crossunder:\n#       up   = fast > slow and fast[1] <= slow[1]\n#       down = fast < slow and fast[1] >= slow[1]\n#       Known at the close of the bar\'s last minute.\n#   E4  Selection at that close: every contract of the side (CE on up, PE on\n#       down) priced at its 1m close of that minute (else its last print\n#       inside the spot bar); keep premium in [min, max] inclusive; pick the\n#       HIGHEST (default) or lowest; ties go to the strike nearer spot. The\n#       contract is FIXED for the life of the setup — no re-selection.\n#   E5  Option trigger: the selected contract\'s EMA(fast/slow) on its own\n#       `opt_tf` bars. "intrabar" (default) evaluates at every 1m close with\n#       the forming bar\'s close = the latest print (what a live chart shows\n#       mid-candle); "bar_close" evaluates only closed bars. CE buys when\n#       fast > slow, PE when fast < slow — checked first at the setup minute\n#       ("if not already"), then each minute until filled/replaced/expired.\n#       Not ready (fewer than opt_min_bars bars of history) = keep waiting.\n#   E6  A setup dies when: the opposite spot cross arrives (replaced), the\n#       entry cutoff is reached, or the day ends. Never carried overnight.\n#   E7  Exits, per 1m option bar, pessimistic order: stop (fixed SL or the\n#       trailing stop, whichever is higher) → target. Touch books AT the\n#       level; a bar that OPENS through it books the open. The trailing stop\n#       uses the peak through the PREVIOUS bar (no same-bar high→low\n#       assumption). Then the opposite spot cross (XOVER) at bar close, then\n#       EOD at the open of the square-off minute.\n#   E9  Arming blackout (EMC_V1_BLACKOUT_20261011): a cross closing on a minute\n#       in [skip_from, skip_to) still exits an opposite position and replaces a\n#       pending setup, but arms nothing itself.\n#   E8  One position at a time. Daily caps: max entries, max LOSING trades\n#       (net of charges < 0) — reaching the losing cap halts new setups for\n#       the day; an open position is always managed to its exit.\n#\n# Fleet convention: no imports from sibling strategy packages; helpers are\n# duplicated here so the module stays self-contained.\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass, field\nfrom typing import Callable, Dict, List, Optional, Sequence, Tuple\n\nSESSION_OPEN_MIN = 9 * 60 + 15        # NSE index grid opens 09:15\nSESSION_LAST_MIN = 15 * 60 + 29       # last 1m bar of the session (15:29) ── EMC_CARRY_20261012 ──\n\n\n@dataclass(frozen=True)\nclass EmcBar:\n    ts: int                            # epoch seconds, bar START, IST grid\n    open: float\n    high: float\n    low: float\n    close: float\n    end_min: int = 0                   # minute-of-day of the bar\'s LAST 1m slot\n\n\n# ─────────────────────────────────────────────────────────────────────────\n#  E1  RESAMPLE — session-aligned tf buckets from 09:15\n# ─────────────────────────────────────────────────────────────────────────\ndef resample_session(bars_1m, *, day_start_epoch: int, tf_minutes: int) -> List[EmcBar]:\n    """bars_1m: objects with ts/open/high/low/close (1m, ascending)."""\n    out: Dict[int, dict] = {}\n    for b in bars_1m:\n        mod = (b.ts - day_start_epoch) // 60\n        if mod < SESSION_OPEN_MIN:\n            continue\n        bucket = (mod - SESSION_OPEN_MIN) // tf_minutes\n        bts = day_start_epoch + (SESSION_OPEN_MIN + bucket * tf_minutes) * 60\n        cur = out.get(bts)\n        if cur is None:\n            out[bts] = {"o": float(b.open), "h": float(b.high), "l": float(b.low), "c": float(b.close),\n                        "end": SESSION_OPEN_MIN + (bucket + 1) * tf_minutes - 1}\n        else:\n            cur["h"] = max(cur["h"], float(b.high))\n            cur["l"] = min(cur["l"], float(b.low))\n            cur["c"] = float(b.close)\n    return [EmcBar(ts, v["o"], v["h"], v["l"], v["c"], v["end"]) for ts, v in sorted(out.items())]\n\n\n# ─────────────────────────────────────────────────────────────────────────\n#  E2  EMA — Pine ta.ema (SMA seed), incremental with a non-committing peek\n# ─────────────────────────────────────────────────────────────────────────\nclass Ema:\n    __slots__ = ("period", "k", "n", "acc", "value")\n\n    def __init__(self, period: int):\n        if period < 1:\n            raise ValueError("ema period must be >= 1")\n        self.period = int(period)\n        self.k = 2.0 / (self.period + 1.0)\n        self.n = 0\n        self.acc = 0.0\n        self.value: Optional[float] = None\n\n    def update(self, x: float) -> Optional[float]:\n        x = float(x)\n        self.n += 1\n        if self.value is None:\n            self.acc += x\n            if self.n == self.period:\n                self.value = self.acc / self.period\n        else:\n            self.value = x * self.k + self.value * (1.0 - self.k)\n        return self.value\n\n    def peek(self, x: float) -> Optional[float]:\n        """The value update(x) WOULD produce, without committing it."""\n        x = float(x)\n        if self.value is None:\n            return (self.acc + x) / self.period if self.n + 1 == self.period else None\n        return x * self.k + self.value * (1.0 - self.k)\n\n\nclass EmaPair:\n    __slots__ = ("fast", "slow")\n\n    def __init__(self, fast: int, slow: int):\n        self.fast = Ema(fast)\n        self.slow = Ema(slow)\n\n    def update(self, x: float) -> Tuple[Optional[float], Optional[float]]:\n        return self.fast.update(x), self.slow.update(x)\n\n    def peek(self, x: float) -> Tuple[Optional[float], Optional[float]]:\n        return self.fast.peek(x), self.slow.peek(x)\n\n    @property\n    def values(self) -> Tuple[Optional[float], Optional[float]]:\n        return self.fast.value, self.slow.value\n\n\ndef ema_series(vals: Sequence[float], period: int) -> List[Optional[float]]:\n    """Batch form of Ema (same arithmetic) — overlays and tests."""\n    e = Ema(period)\n    return [e.update(v) for v in vals]\n\n\n# ─────────────────────────────────────────────────────────────────────────\n#  E3  CROSS / ALIGNMENT\n# ─────────────────────────────────────────────────────────────────────────\ndef crossed(pf: Optional[float], ps: Optional[float], f: Optional[float], s: Optional[float]) -> int:\n    """+1 crossover, −1 crossunder, 0 none (Pine semantics; any None → 0)."""\n    if pf is None or ps is None or f is None or s is None:\n        return 0\n    if f > s and pf <= ps:\n        return 1\n    if f < s and pf >= ps:\n        return -1\n    return 0\n\n\ndef aligned(side: str, f: Optional[float], s: Optional[float]) -> bool:\n    if f is None or s is None:\n        return False\n    return f > s if side == "CE" else f < s\n\n\ndef spot_crosses(bars: Sequence[EmcBar], pair: EmaPair) -> Dict[int, int]:\n    """Advance the (continuous) spot EMA pair over one session\'s closed bars;\n    returns {bar end minute: ±1} for every cross on this session."""\n    out: Dict[int, int] = {}\n    for b in bars:\n        pf, ps = pair.values\n        f, s = pair.update(b.close)\n        x = crossed(pf, ps, f, s)\n        if x:\n            out[b.end_min] = x\n    return out\n\n\n# ─────────────────────────────────────────────────────────────────────────\n#  E4  SELECTION\n# ─────────────────────────────────────────────────────────────────────────\ndef pick_in_band(quotes: Sequence[dict], lo: float, hi: float, *, pick: str = "highest",\n                 spot: Optional[float] = None) -> Optional[dict]:\n    """quotes: [{sym, strike, price}]. Band inclusive both ends."""\n    inb = [q for q in quotes if q.get("price") is not None and lo <= float(q["price"]) <= hi]\n    if not inb:\n        return None\n\n    def money(q):\n        return abs(float(q.get("strike") or 0.0) - float(spot)) if spot is not None else 0.0\n\n    if pick == "lowest":\n        return min(inb, key=lambda q: (float(q["price"]), money(q), str(q["sym"])))\n    return min(inb, key=lambda q: (-float(q["price"]), money(q), str(q["sym"])))\n\n\n# ─────────────────────────────────────────────────────────────────────────\n#  E5  OPTION EMA TRACK\n# ─────────────────────────────────────────────────────────────────────────\nclass OptionEmaTrack:\n    """The selected contract\'s EMA pair on opt_tf bars: warm history (closed\n    bars from prior sessions) + today\'s 1m prints, evaluated causally."""\n\n    def __init__(self, *, fast: int, slow: int, tf: int, ds: int,\n                 warm_bars: Sequence[EmcBar], today_1m: Sequence):\n        self.pair = EmaPair(fast, slow)\n        self.nbars = 0\n        for b in warm_bars:\n            self.pair.update(b.close)\n            self.nbars += 1\n        self.warm_bars = len(warm_bars)\n        self.ds = ds\n        self.tf = tf\n        self.today = resample_session(today_1m, day_start_epoch=ds, tf_minutes=tf)\n        self.by_min = {(c.ts - ds) // 60: c for c in today_1m}\n        self.idx = 0\n        self.last_k = -1\n\n    def at(self, k: int, intrabar: bool = True) -> Tuple[Optional[float], Optional[float], int]:\n        """(fast, slow, bars used) as of the CLOSE of minute k. Calls must be\n        non-decreasing in k (the runner walks minutes forward)."""\n        if k < self.last_k:\n            raise ValueError("OptionEmaTrack.at called backwards in time")\n        self.last_k = k\n        while self.idx < len(self.today) and self.today[self.idx].end_min <= k:\n            self.pair.update(self.today[self.idx].close)\n            self.nbars += 1\n            self.idx += 1\n        if intrabar and self.idx < len(self.today):\n            b = self.today[self.idx]\n            start = (b.ts - self.ds) // 60\n            if start <= k:\n                for m in range(k, start - 1, -1):\n                    c = self.by_min.get(m)\n                    if c is not None:\n                        f, s = self.pair.peek(c.close)\n                        return f, s, self.nbars + 1\n        f, s = self.pair.values\n        return f, s, self.nbars\n\n\n# ─────────────────────────────────────────────────────────────────────────\n#  E7  FILLS / TRAIL\n# ─────────────────────────────────────────────────────────────────────────\ndef stop_fill(level: float, bar) -> Optional[float]:\n    if float(bar.open) <= level:\n        return float(bar.open)\n    if float(bar.low) <= level:\n        return float(level)\n    return None\n\n\ndef target_fill(level: float, bar) -> Optional[float]:\n    if float(bar.open) >= level:\n        return float(bar.open)\n    if float(bar.high) >= level:\n        return float(level)\n    return None\n\n\n# ── EMC_SELL_20261012 ── the SHORT mirrors: the loss is premium RISING.\ndef stop_fill_short(level: float, bar) -> Optional[float]:\n    if float(bar.open) >= level:\n        return float(bar.open)\n    if float(bar.high) >= level:\n        return float(level)\n    return None\n\n\ndef target_fill_short(level: float, bar) -> Optional[float]:\n    if float(bar.open) <= level:\n        return float(bar.open)\n    if float(bar.low) <= level:\n        return float(level)\n    return None\n\n\ndef effective_stop_short(*, entry: float, trough: float, sl_level: Optional[float], trail_on: bool,\n                         trail_trigger: float, trail_gap: float) -> Tuple[Optional[float], bool]:\n    """Short trail: once the premium has FALLEN by the trigger, the stop\n    trails `gap` above the lowest premium seen (never above the fixed SL)."""\n    if trail_on and trail_gap > 0 and (entry - trough) >= trail_trigger:\n        t = trough + trail_gap\n        if sl_level is None or t < sl_level:\n            return t, True\n    return sl_level, False\n\n\ndef effective_stop(*, entry: float, peak: float, sl_level: Optional[float], trail_on: bool,\n                   trail_trigger: float, trail_gap: float) -> Tuple[Optional[float], bool]:\n    """(stop level, trailing?) — trailing once the peak gain reaches the\n    trigger; the stop never sits below the fixed SL."""\n    if trail_on and trail_gap > 0 and (peak - entry) >= trail_trigger:\n        t = peak - trail_gap\n        if sl_level is None or t > sl_level:\n            return t, True\n    return sl_level, False\n\n\n# ─────────────────────────────────────────────────────────────────────────\n#  E4–E8  ONE SESSION\n# ─────────────────────────────────────────────────────────────────────────\n@dataclass\nclass DayParams:\n    sel_lo: float\n    sel_hi: float\n    sel_pick: str                      # highest | lowest\n    direction: str                     # BOTH | CE | PE\n    intrabar: bool\n    opt_min_bars: int\n    fill: str                          # close | next_open\n    sl_pts: float                      # 0 = off\n    tp_pts: float                      # 0 = off\n    trail_on: bool\n    trail_trigger: float\n    trail_gap: float\n    xover_exit: bool\n    block_min: int                     # first minute with NO new entries\n    eod_min: int                       # square-off minute (exit at its open)\n    max_trades: int                    # 0 = unlimited\n    max_losses: int                    # 0 = unlimited\n    # ── EMC_V1_BLACKOUT_20261011 ── a spot cross whose candle closes on a minute\n    # in [skip_from, skip_to) arms nothing (it still exits / replaces as usual)\n    skip_from: int = -1\n    skip_to: int = -1\n    # ── EMC_SELL_20261012 ── leg action SELL (backtest only): an up cross\n    # SELLS the PE, a down cross SELLS the CE; the sold option\'s own EMA must\n    # be falling (fast < slow); SL above / TP below the entry premium.\n    sell: bool = False\n\n\n@dataclass\nclass DayTrade:\n    side: str\n    sym: str\n    strike: Optional[float]\n    sel_min: int\n    sel_px: float\n    entry_min: int\n    entry_px: float\n    sl: Optional[float]\n    tp: Optional[float]\n    exit_min: Optional[int] = None\n    exit_px: Optional[float] = None\n    reason: Optional[str] = None\n    waited: int = 0                    # minutes from setup to the trigger\n    aligned_at_setup: bool = False\n    opt_bars: int = 0\n    mae: float = 0.0                   # per unit premium\n    mfe: float = 0.0\n    entry_spot: Optional[float] = None\n    trail_armed: bool = False\n    net: float = 0.0\n    sell: bool = False                 # ── EMC_SELL_20261012 ── a short leg\n    # ── EMC_CARRY_20261012 ── set by the runner only on a position carried\n    # overnight: its own quantity (sizing may differ on the closing day), the\n    # entry day\'s start epoch, and the nights held. None/0 = an intraday trade.\n    qty: Optional[int] = None\n    entry_ds: Optional[int] = None\n    nights: int = 0\n\n\nclass EmcDayCore:\n    """E4–E8 for ONE session as a stateful object — the decision code the\n    backtest (simulate_day) and the paper/live engine (EMC_V1_LIVE_20261011)\n    BOTH run. Minute k means the 1m bar that starts at k; decisions are taken\n    at its CLOSE. Fills are injected, so the same decisions execute against\n    corpus bars (backtest) or against the broker / paper quotes (live):\n\n      quotes_at(k, side)        → [{sym, strike, price}] at the close of k\n      track_of(contract)        → object with .at(k, intrabar) → (fast, slow, bars)\n      spot_at(k)                → spot close of minute k (or None)\n      net_of(entry, exit)       → net rupees of a round trip (charges included)\n      fill_entry(sym, k)        → (price, minute) or (None, k) when unfillable\n      fill_exit(sym, k, last)   → (price, minute) for an opposite-cross exit\n\n    Stop / target exits on 1m bars are the backtest\'s job (bar_exits); live\n    exits them intraminute and reports back through external_close() so the\n    daily losing-trade cap counts every exit identically.\n    ── EMC_V1_LIVE_20261011 ── refactor of simulate_day; outputs proven\n    identical to the pre-refactor engine by test_emc_live.py."""\n\n    def __init__(self, *, p: DayParams, quotes_at, track_of, spot_at, net_of, fill_entry, fill_exit,\n                 diag: dict, bars_of=None, session_open: int = SESSION_OPEN_MIN, trade_net=None):\n        self.p = p\n        # ── EMC_SELL_20261012 ── optional trade_net(t, exit_px, k_exit) → net:\n        # the backtest supplies it for SELL so the losing-trade cap counts the\n        # short + wing pair exactly as the trade row books it.\n        self.trade_net = trade_net\n        self.quotes_at, self.track_of, self.spot_at = quotes_at, track_of, spot_at\n        self.net_of, self.fill_entry, self.fill_exit = net_of, fill_entry, fill_exit\n        self.bars_of = bars_of\n        self.D = diag\n        self.session_open = session_open\n        self.trades: List[DayTrade] = []\n        self.pos: Optional[dict] = None\n        self.setup: Optional[dict] = None\n        self.day_entries = 0\n        self.day_losses = 0\n        self.halted = False\n\n    # ── helpers ──\n    def _bump(self, key, n=1):\n        self.D[key] = self.D.get(key, 0) + n\n\n    def can_enter(self, k: int) -> Optional[str]:\n        p = self.p\n        if self.halted:\n            return "losses"\n        if p.max_trades and self.day_entries >= p.max_trades:\n            return "trades"\n        if k >= p.block_min:\n            return "cutoff"\n        return None\n\n    def _record_close(self, k_exit: int, px: float, reason: str, net: Optional[float] = None) -> DayTrade:\n        t: DayTrade = self.pos["t"]\n        t.exit_min, t.exit_px, t.reason = k_exit, round(float(px), 2), reason\n        if net is not None:\n            t.net = float(net)\n        elif self.trade_net is not None:               # ── EMC_SELL_20261012 ──\n            t.net = float(self.trade_net(t, float(px), k_exit))\n        elif t.qty is None:\n            t.net = self.net_of(t.entry_px, float(px))\n        else:                                          # ── EMC_CARRY_20261012 ── carried: its own qty\n            t.net = self.net_of(t.entry_px, float(px), t.qty)\n        self.trades.append(t)\n        if t.net < 0:\n            self.day_losses += 1\n            if self.p.max_losses and self.day_losses >= self.p.max_losses and not self.halted:\n                self.halted = True\n                self._bump("days_halted_losses")\n        self.pos = None\n        return t\n\n    def external_close(self, k_exit: int, px: float, reason: str, net: Optional[float] = None) -> Optional[DayTrade]:\n        """Live: the engine closed the position itself (SL/TP/EOD/kill)."""\n        if self.pos is None:\n            return None\n        return self._record_close(k_exit, px, reason, net)\n\n    def adopt_position(self, t: DayTrade, *, check_from: int) -> None:\n        """Live restart: graft an already-open position back in."""\n        self.pos = {"t": t, "check_from": check_from, "peak": t.entry_px, "last": t.entry_px}\n\n    def _try_enter(self, k: int, first: bool) -> bool:\n        p = self.p\n        setup = self.setup\n        f, s, n = setup["track"].at(k, p.intrabar)\n        ready = f is not None and s is not None and n >= p.opt_min_bars\n        if not ready:\n            setup["unready"] = True\n            return False\n        if p.sell:                                     # ── EMC_SELL_20261012 ── sold premium must be falling\n            if not (f < s):\n                return False\n        elif not aligned(setup["side"], f, s):\n            return False\n        if self.can_enter(k):\n            return False\n        sym = setup["c"]["sym"]\n        px, kmin = self.fill_entry(sym, k)\n        if px is None or px <= 0:\n            self._bump("sig_no_fill")\n            self.setup = None\n            return False\n        if p.sell:                                     # ── EMC_SELL_20261012 ── levels invert for a short\n            sl = round(px + p.sl_pts, 2) if p.sl_pts > 0 else None\n            tp = round(px - p.tp_pts, 2) if p.tp_pts > 0 else None\n        else:\n            sl = round(px - p.sl_pts, 2) if p.sl_pts > 0 else None\n            tp = round(px + p.tp_pts, 2) if p.tp_pts > 0 else None\n        t = DayTrade(side=setup["side"], sym=sym, strike=setup["c"].get("strike"),\n                     sel_min=setup["k"], sel_px=float(setup["c"]["price"]),\n                     entry_min=kmin, entry_px=round(px, 2), sl=sl, tp=tp,\n                     waited=k - setup["k"], aligned_at_setup=first, opt_bars=n,\n                     entry_spot=self.spot_at(k), sell=bool(p.sell))\n        self.pos = {"t": t, "check_from": k + 1, "peak": px, "last": px}\n        self.day_entries += 1\n        self._bump("entries")\n        self._bump("entries_aligned_at_setup" if first else "entries_after_wait")\n        if setup.get("unready"):\n            self._bump("entries_after_warmup_wait")\n        self.setup = None\n        return True\n\n    # ── (a) stop / target on minute k\'s option bar — BACKTEST ONLY ──\n    def bar_exits(self, k: int) -> None:\n        p = self.p\n        pos = self.pos\n        if pos is None or pos["check_from"] > k:\n            return\n        t: DayTrade = pos["t"]\n        b = self.bars_of(t.sym).get(k)\n        if b is None:\n            self._bump("stale_marks")\n            return\n        if t.sell:                                     # ── EMC_SELL_20261012 ── short leg\n            stop, trailing = effective_stop_short(entry=t.entry_px, trough=pos["peak"], sl_level=t.sl,\n                                                  trail_on=p.trail_on, trail_trigger=p.trail_trigger,\n                                                  trail_gap=p.trail_gap)\n            if trailing:\n                t.trail_armed = True\n            hit = None\n            if stop is not None:\n                px = stop_fill_short(stop, b)\n                if px is not None:\n                    hit = ("TSL" if trailing else "SL", px)\n            if hit is None and t.tp is not None:\n                px = target_fill_short(t.tp, b)\n                if px is not None:\n                    hit = ("TP", px)\n            t.mae = min(t.mae, t.entry_px - float(b.high))\n            t.mfe = max(t.mfe, t.entry_px - float(b.low))\n            if hit is not None:\n                self._record_close(k, hit[1], hit[0])\n            else:\n                pos["peak"] = min(pos["peak"], float(b.low))      # the trough, for a short\n                pos["last"] = float(b.close)\n            return\n        stop, trailing = effective_stop(entry=t.entry_px, peak=pos["peak"], sl_level=t.sl,\n                                        trail_on=p.trail_on, trail_trigger=p.trail_trigger,\n                                        trail_gap=p.trail_gap)\n        if trailing:\n            t.trail_armed = True\n        hit = None\n        if stop is not None:\n            px = stop_fill(stop, b)\n            if px is not None:\n                hit = ("TSL" if trailing else "SL", px)\n        if hit is None and t.tp is not None:\n            px = target_fill(t.tp, b)\n            if px is not None:\n                hit = ("TP", px)\n        t.mae = min(t.mae, float(b.low) - t.entry_px)\n        t.mfe = max(t.mfe, float(b.high) - t.entry_px)\n        if hit is not None:\n            self._record_close(k, hit[1], hit[0])\n        else:\n            pos["peak"] = max(pos["peak"], float(b.high))\n            pos["last"] = float(b.close)\n\n    # ── (b) + (c) at the close of minute k ──\n    def on_minute_close(self, k: int, x: int) -> None:\n        p = self.p\n        if x:\n            dside = "CE" if x > 0 else "PE"            # the cross direction (bullish = "CE")\n            side = (("PE" if x > 0 else "CE") if p.sell else dside)   # ── EMC_SELL_20261012 ── the instrument traded\n            self._bump("crosses_up" if x > 0 else "crosses_dn")\n            if self.pos is not None and self.pos["t"].side != side and p.xover_exit:\n                px, kx = self.fill_exit(self.pos["t"].sym, k, self.pos["last"])\n                if px is not None:\n                    self._record_close(kx, px, "XOVER")\n            if self.setup is not None and self.setup["side"] != side:\n                self._bump("setups_replaced")\n                self.setup = None\n            if p.skip_from >= 0 and p.skip_from <= k < p.skip_to:   # ── EMC_V1_BLACKOUT_20261011 ──\n                self._bump("sig_dropped_blackout")\n            elif p.direction not in ("BOTH", dside):\n                self._bump("sig_dropped_dir")\n            elif self.pos is not None:\n                self._bump("sig_dropped_open")\n            else:\n                why = self.can_enter(k)\n                if why:\n                    self._bump(f"sig_dropped_{why}")\n                else:\n                    qs = self.quotes_at(k, side)\n                    if not qs:\n                        self._bump("setup_no_universe")\n                    else:\n                        c = pick_in_band(qs, p.sel_lo, p.sel_hi, pick=p.sel_pick, spot=self.spot_at(k))\n                        if c is None:\n                            self._bump("setup_no_band")\n                        else:\n                            self.setup = {"side": side, "c": c, "k": k, "track": self.track_of(c),\n                                          "unready": False}\n                            self._bump("setups")\n                            self._try_enter(k, first=True)\n                            return                  # this minute\'s check is done\n        if self.setup is not None and self.pos is None:\n            if k >= p.block_min or self.halted or (p.max_trades and self.day_entries >= p.max_trades):\n                self._bump("setups_expired_cutoff")\n                self.setup = None\n            else:\n                self._try_enter(k, first=False)\n\n    # ── (d) end of session ──\n    def finish(self, eod_px: Optional[float]) -> None:\n        """Expire a pending setup; close an open position at eod_px (the\n        open of the square-off minute; None → last mark)."""\n        p = self.p\n        if self.setup is not None:\n            self._bump("setups_expired_eod")\n            if self.setup.get("unready"):\n                self._bump("setups_expired_unready")\n            self.setup = None\n        if self.pos is not None:\n            px = eod_px if eod_px else self.pos["last"]\n            self._record_close(p.eod_min, px, "EOD")\n        if self.day_entries and p.max_trades and self.day_entries >= p.max_trades:\n            self._bump("days_capped_trades")\n\n\ndef simulate_day(*, p: DayParams, cross_at: Dict[int, int], quotes_at: Callable[[int, str], List[dict]],\n                 bars_of: Callable[[str], Dict[int, object]], track_of: Callable[[dict], object],\n                 net_of: Callable[[float, float], float], spot_at: Callable[[int], Optional[float]],\n                 diag: dict, session_open: int = SESSION_OPEN_MIN, carry: Optional[dict] = None,\n                 trade_net=None, entry_hook=None) -> List[DayTrade]:\n    """Walk one session minute by minute through EmcDayCore with corpus-bar\n    fills. Returns closed trades.\n\n    ── EMC_CARRY_20261012 ── carry (backtest only; None = the sealed intraday\n    behaviour, byte-identical): {"in": a position dict carried from the\n    previous session or None, "ok": callable(DayTrade) → bool — may the\n    position open at EOD be carried tonight (False on its contract\'s expiry\n    day)}. On return carry["out"] holds the position carried into the next\n    session (or None). A carried position is managed through the rest of the\n    session (15:15 → 15:29: stop / target on bars, opposite-cross exit) and\n    from the next session\'s first bar (a gap through a level books the open).\n\n    quotes_at(k, side) → [{sym, strike, price}] at the close of minute k\n    bars_of(sym)       → {minute: bar(open/high/low/close)}\n    track_of(contract) → object with .at(k, intrabar) → (fast, slow, bars)\n    net_of(entry, exit)→ net rupees of a round trip (charges included)."""\n\n    def fill_px(sym: str, k: int, last: Optional[float]):\n        bars = bars_of(sym)\n        if p.fill == "next_open":\n            nb = bars.get(k + 1)\n            if nb is not None and nb.open:\n                return float(nb.open), k + 1\n            diag["fill_fallbacks"] = diag.get("fill_fallbacks", 0) + 1\n        b = bars.get(k)\n        if b is not None and b.close:\n            return float(b.close), k\n        return last, k\n\n    def _entry(sym: str, k: int):\n        px, km = fill_px(sym, k, None)\n        # ── EMC_SELL_20261012 ── entry_hook(sym, fill_minute, px) → False vetoes\n        # the fill (a SELL whose protective wing cannot be bought: no wing → no trade)\n        if px is not None and px > 0 and entry_hook is not None and not entry_hook(sym, km, px):\n            return None, k\n        return px, km\n\n    core = EmcDayCore(p=p, quotes_at=quotes_at, track_of=track_of, spot_at=spot_at, net_of=net_of,\n                      fill_entry=_entry,\n                      fill_exit=fill_px, diag=diag, bars_of=bars_of, session_open=session_open,\n                      trade_net=trade_net)\n    if carry is not None:\n        carry["out"] = None\n        if carry.get("in") is not None:\n            core.pos = carry["in"]\n            core.pos["check_from"] = session_open\n    for k in range(session_open, p.eod_min):\n        core.bar_exits(k)\n        core.on_minute_close(k, cross_at.get(k, 0))\n    if carry is not None and core.pos is not None and carry["ok"](core.pos["t"]):\n        # ── EMC_CARRY_20261012 ── hold through the close; no new entries can\n        # arm here (every minute is past the entry cutoff ≤ square-off).\n        if core.setup is not None:\n            diag["setups_expired_eod"] = diag.get("setups_expired_eod", 0) + 1\n            core.setup = None\n        for k in range(p.eod_min, SESSION_LAST_MIN + 1):\n            if core.pos is None:\n                break\n            core.bar_exits(k)\n            if core.pos is not None and cross_at.get(k, 0):\n                x = cross_at[k]\n                diag["crosses_up" if x > 0 else "crosses_dn"] = diag.get("crosses_up" if x > 0 else "crosses_dn", 0) + 1\n                inst = (("PE" if x > 0 else "CE") if p.sell else ("CE" if x > 0 else "PE"))   # ── EMC_SELL_20261012 ──\n                if core.pos["t"].side != inst and p.xover_exit:\n                    px, kx = fill_px(core.pos["t"].sym, k, core.pos["last"])\n                    if px is not None:\n                        core._record_close(min(kx, SESSION_LAST_MIN), px, "XOVER")\n        if core.pos is not None:\n            carry["out"] = core.pos\n            core.pos = None\n            diag["carry_nights"] = diag.get("carry_nights", 0) + 1\n    eod_px = None\n    if core.pos is not None:\n        b = bars_of(core.pos["t"].sym).get(p.eod_min)\n        eod_px = float(b.open) if (b is not None and b.open) else None\n    core.finish(eod_px)\n    return core.trades\n')

REPLACE['backend/app/backtest/emc/backtest_emc_runner.py'] = ('e3217ba83165e90584d23128fa0c2f530b97381575535c6f4ea7abb8e34b2a9b', '# backend/app/backtest/emc/backtest_emc_runner.py\n#\n# ── EMC_V1 RUNNER ── "Ember": NIFTY SPOT EMA(9/21) cross arms a weekly option\n# picked by premium band; the option\'s own EMA(9/21) alignment buys it.\n#\n# Fence: EMC_V1_20261011\n#\n# Decision core (E1–E8) lives in emc_v1_engine.py (simulate_day). This\n# module owns data access and bookkeeping only:\n#   R1  Spot: 1m SPOT → spot_tf bars; the spot EMA pair is continuous across\n#       sessions, warmed on `warmup_sessions` sessions before date_from, and\n#       advanced on EVERY session with spot data — including sessions the\n#       strategy does not trade (skip-expiry, DTE skip, no chain).\n#   R2  Chain: the expected weekly expiry for the day (same calendar as every\n#       other runner), contracts with any print that day.\n#   R3  Option EMA warm-up: the selected contract\'s 1m prints from up to\n#       `opt_warmup_sessions` earlier sessions (whatever the corpus holds for\n#       that symbol — on the first session of a weekly cycle the new front\n#       contract usually has none), resampled per session to opt_tf.\n#       Fewer than opt_min_bars bars = not ready = keep waiting (counted).\n#   R4  Charges: charges_for_long_trade on every round trip; a "losing trade"\n#       for the daily cap is net of charges < 0.\n#   R6  First-candle cross (EMC_V1_FIX1_20261011): the session\'s first spot\n#       candle\'s cross is measured against YESTERDAY\'s last candle, so it is\n#       made by the overnight gap. first_candle_cross=False drops it (counted\n#       in gap_crosses_ignored); gap_crosses counts them either way.\n#   R7  Carry overnight (EMC_CARRY_20261012, backtest only, default OFF): the\n#       position open at the square-off is carried unless today is its\n#       contract\'s expiry day; a carried position keeps its entry-day qty, is\n#       managed on every later session — including sessions skipped for\n#       entries (skip-expiry, DTE skip, no cross: entries blocked, exits live)\n#       — and counts toward the losing-trade cap of the day it closes.\n#       A session with no spot data cannot manage it (counted; carried on).\n#       Open at the end of the run → closed at its last mark (RUN_END).\n#   R5  Sizing: lots × lot size, then DTE × lots, then lot compounding — the\n#       fleet order (DTE_LOT_MULT_20260911, LOT_COMP_20260924).\n#\n# ── FALSIFICATION TRIPWIRES (read the run diag before the P&L) ──────────\n#   * setup_no_band vs setups — a band that rejects most crosses tests a\n#     much sparser strategy than the chart suggests (STFC scar: 75%).\n#   * entries_aligned_at_setup vs entries_after_wait — if almost every entry\n#     is "already aligned", the option-EMA gate is decorative.\n#   * xover_pnl_share_pct vs sl/tp — which exit actually carries the net.\n#   * entries_after_warmup_wait / setups_expired_unready — weekly-cycle day\n#     one has no option history in the corpus; the gate behaves differently.\n#   * ce_net vs pe_net and the Sessions-to-Expiry breakdown.\n\nfrom __future__ import annotations\n\nimport uuid\nfrom dataclasses import dataclass, field\nfrom datetime import date, datetime, timedelta\nfrom typing import Callable, Dict, List, Optional\n\ntry:\n    from app.backtest.emc.emc_v1_engine import (\n        EmcBar, EmaPair, OptionEmaTrack, DayParams, resample_session, spot_crosses,\n        simulate_day, SESSION_OPEN_MIN, SESSION_LAST_MIN)\nexcept ImportError:                                        # standalone tests\n    from emc_v1_engine import (  # type: ignore\n        EmcBar, EmaPair, OptionEmaTrack, DayParams, resample_session, spot_crosses,\n        simulate_day, SESSION_OPEN_MIN, SESSION_LAST_MIN)\n\nIST_OFFSET = 5 * 3600 + 30 * 60\nINDEX_LOTS = {"NIFTY": 65, "BANKNIFTY": 35}\nMIN_PER_SESSION = 375\n\nDEFAULTS: dict = {\n    # ── signal ──\n    "spot_tf": 5,                      # spot bar minutes\n    "opt_tf": 5,                       # option bar minutes\n    "ema_fast": 9,\n    "ema_slow": 21,\n    "warmup_sessions": 5,              # spot EMA warm-up before date_from\n    "opt_warmup_sessions": 3,          # option history sessions loaded\n    "opt_min_bars": 0,                 # 0 = ema_slow\n    "opt_check": "intrabar",           # intrabar | bar_close\n    "direction": "BOTH",               # BOTH | CE | PE\n\n    # ── selection ──\n    "sel_prem_min": 150.0,\n    "sel_prem_max": 200.0,\n    "sel_pick": "highest",             # highest | lowest\n\n    # ── execution & exits ──\n    "fill_mode": "next_open",          # next_open | close\n    "sl_pts": 20.0,                    # premium points; 0 = off\n    "tp_pts": 40.0,                    # premium points; 0 = off\n    "trail_on": False,\n    "trail_trigger_pts": 20.0,         # gain (pts) that arms the trail; 0 = from entry\n    "trail_gap_pts": 15.0,             # trail distance below the peak\n    "xover_exit": True,                # exit on the opposite spot cross\n\n    # ── session & budgets ──\n    "entry_cutoff": "14:30",\n    "eod_square_off": "15:15",\n    "max_trades_per_day": 0,           # 0 = unlimited\n    "max_losses_per_day": 0,           # 0 = unlimited\n    "lots": 1,\n    "lot_size": 0,                     # 0 = index constant\n    "skip_expiry_day": False,\n    # ── EMC_V1_FIX1_20261011 ── a cross on the session\'s FIRST spot candle is\n    # usually made by the overnight gap (yesterday\'s last candle → today\'s\n    # first). True = count it (TradingView-continuous); False = it arms nothing.\n    "first_candle_cross": True,\n    # ── EMC_CARRY_20261012 ── BACKTEST ONLY. True = a position still open at\n    # the square-off is carried to the next session (managed 15:15→15:29 and\n    # from the next open: SL / TP on bars, gap through a level books the open,\n    # opposite-cross exit). On its contract\'s EXPIRY day it exits at the\n    # square-off as usual. Default False = the sealed intraday strategy.\n    "carry_overnight": False,\n    # ── EMC_SELL_20261012 ── BACKTEST ONLY. Leg action, VET V1\'s convention:\n    # BUY = an up cross buys the CE, a down cross buys the PE (the sealed\n    # strategy). SELL = an up cross SELLS the PE, a down cross SELLS the CE;\n    # selection band / pick apply to the sold contract; the sold option\'s\n    # own EMA fast must be BELOW slow (its premium falling) to trigger; SL is\n    # sl_pts ABOVE the entry premium, TP tp_pts BELOW; the opposite spot\n    # cross still exits. Optional protective wing (hedge) — VET\'s rule: a\n    # long option, same type & expiry, the DEAREST one at or under\n    # hedge_max_premium (real print first, model-priced fallback); no wing →\n    # no trade. One row per position carrying the PAIR\'s P&L.\n    "leg_action": "BUY",\n    "hedge_enabled": False,\n    "hedge_max_premium": 5.0,\n    "hedge_synth_enabled": True,\n    "hedge_skew_mult": 1.0,\n    # ── EMC_V1_BLACKOUT_20261011 ── skip setups armed in [from, to) — HH:MM,\n    # both blank = off. Matches on the arming candle\'s LAST minute (the "arm"\n    # time in the trade condition), e.g. 09:30–10:00 skips arms 09:30…09:59.\n    "arm_skip_from": "",\n    "arm_skip_to": "",\n}\n\n\n@dataclass\nclass EMCTrade:\n    """persist_run-compatible attribute surface (same shape as STFCTrade)."""\n    tradingsymbol: str\n    symbol: str\n    instrument_type: str\n    strike: Optional[float]\n    expiry: Optional[str]\n    direction: str                     # always BUY\n    entry_ts: int\n    entry_price: float\n    sl: Optional[float]                # initial premium stop\n    tp: Optional[float]                # premium target\n    exit_ts: Optional[int]\n    exit_price: Optional[float]\n    exit_reason: Optional[str]         # SL | TSL | TP | XOVER | EOD\n    qty: int\n    condition: str\n    ambiguous_fill: bool = False\n    pnl: float = 0.0\n    charges: float = 0.0\n    net_pnl: float = 0.0\n    max_adverse: Optional[float] = None\n    max_favorable: Optional[float] = None\n    gross: float = field(default=0.0)\n    net: float = field(default=0.0)\n    ambiguous: bool = field(default=False)\n    synthetic: bool = field(default=False)\n    synth_kind: Optional[str] = field(default=None)\n    entry_spot: Optional[float] = None\n    hold_min: int = 0\n    # ── EMC_SELL_20261012 ── the protective wing of a SELL, for transparency.\n    # Deliberately NOT named hedge_symbol (backtest_repo switches on that name\n    # and would store the wing as the primary row — VET\'s note).\n    wing_symbol: Optional[str] = None\n    wing_entry: Optional[float] = None\n    wing_exit: Optional[float] = None\n\n\ndef _empty_summary() -> dict:\n    return {"total_trades": 0, "wins": 0, "losses": 0, "win_rate": 0.0,\n            "gross_pnl": 0.0, "total_charges": 0.0, "net_pnl": 0.0,\n            "max_drawdown": 0.0, "ambiguous_fills": 0}\n\n\ndef _hhmm(s, fallback: int) -> int:\n    try:\n        h, m = str(s).strip().split(":")\n        v = int(h) * 60 + int(m)\n        return v if 0 <= v < 24 * 60 else fallback\n    except (ValueError, AttributeError):\n        return fallback\n\n\ndef _day_start_epoch(d: date) -> int:\n    return int((datetime(d.year, d.month, d.day) - datetime(1970, 1, 1)).total_seconds()) - IST_OFFSET\n\n\ndef _ist_date(ts: int) -> date:\n    return (datetime(1970, 1, 1) + timedelta(seconds=int(ts) + IST_OFFSET)).date()\n\n\ndef _merge_cfg(override: Optional[dict]) -> dict:\n    cfg = dict(DEFAULTS)\n    for k, v in (override or {}).items():\n        cfg[k] = v\n    _d = str(cfg.get("direction", "BOTH")).upper()\n    cfg["direction"] = _d if _d in ("BOTH", "CE", "PE") else "BOTH"\n    cfg["opt_check"] = "bar_close" if str(cfg.get("opt_check", "intrabar")).lower() == "bar_close" else "intrabar"\n    cfg["sel_pick"] = "lowest" if str(cfg.get("sel_pick", "highest")).lower() == "lowest" else "highest"\n    cfg["fill_mode"] = "close" if str(cfg.get("fill_mode", "next_open")).lower() == "close" else "next_open"\n    for k in ("spot_tf", "opt_tf", "ema_fast", "ema_slow", "warmup_sessions", "opt_warmup_sessions",\n              "opt_min_bars", "max_trades_per_day", "max_losses_per_day", "lots", "lot_size"):\n        try:\n            cfg[k] = max(0, int(cfg[k] or 0))\n        except (TypeError, ValueError):\n            cfg[k] = int(DEFAULTS[k])\n    for k in ("sel_prem_min", "sel_prem_max", "sl_pts", "tp_pts", "trail_trigger_pts", "trail_gap_pts"):\n        try:\n            cfg[k] = abs(float(cfg[k] or 0.0))\n        except (TypeError, ValueError):\n            cfg[k] = float(DEFAULTS[k])\n    for k in ("trail_on", "xover_exit", "skip_expiry_day", "first_candle_cross", "carry_overnight",\n              "hedge_enabled", "hedge_synth_enabled"):   # ── EMC_CARRY_20261012 ── ── EMC_SELL_20261012 ──   # ── EMC_V1_FIX1_20261011 ──\n        v = cfg.get(k, DEFAULTS[k])\n        cfg[k] = (str(v).strip().lower() in ("1", "true", "yes", "on")) if isinstance(v, str) else bool(v)\n    for k in ("arm_skip_from", "arm_skip_to"):   # ── EMC_V1_BLACKOUT_20261011 ──\n        cfg[k] = str(cfg.get(k) or "").strip()\n    cfg["leg_action"] = "SELL" if str(cfg.get("leg_action", "BUY")).strip().upper() == "SELL" else "BUY"   # ── EMC_SELL_20261012 ──\n    for k in ("hedge_max_premium", "hedge_skew_mult"):\n        try:\n            cfg[k] = abs(float(cfg.get(k) if cfg.get(k) is not None else DEFAULTS[k]))\n        except (TypeError, ValueError):\n            cfg[k] = float(DEFAULTS[k])\n    cfg["hedge_skew_mult"] = cfg["hedge_skew_mult"] or 1.0\n    cfg["lots"] = cfg["lots"] or 1\n    cfg["spot_tf"] = cfg["spot_tf"] or 5\n    cfg["opt_tf"] = cfg["opt_tf"] or 5\n    cfg["ema_fast"] = cfg["ema_fast"] or 9\n    cfg["ema_slow"] = cfg["ema_slow"] or 21\n    from app.backtest.engine.dte_lots import parse_dte_lot_mult   # ── DTE_LOT_MULT_20260911 ──\n    cfg["dte_lot_mult"] = parse_dte_lot_mult(cfg.get("dte_lot_mult"))\n    return cfg\n\n\ndef run_emc_backtest(\n    *, db_path: str, strategy_id: str, underlying: str,\n    date_from: date, date_to: date,\n    config_override: Optional[dict] = None,\n    progress_cb: Optional[Callable[[dict], None]] = None,\n    cancel_cb: Optional[Callable[[], bool]] = None,\n) -> Dict:\n    try:\n        from app.event_bus.audit_logger import audit_muted\n        with audit_muted():\n            return _impl(db_path=db_path, strategy_id=strategy_id, underlying=underlying,\n                         date_from=date_from, date_to=date_to, config_override=config_override,\n                         progress_cb=progress_cb, cancel_cb=cancel_cb)\n    except ImportError:\n        return _impl(db_path=db_path, strategy_id=strategy_id, underlying=underlying,\n                     date_from=date_from, date_to=date_to, config_override=config_override,\n                     progress_cb=progress_cb, cancel_cb=cancel_cb)\n\n\ndef _abort(cfg, strategy_id, reason) -> Dict:\n    return {"run_id": None, "aborted": True, "reason": reason, "trades": [],\n            "summary": _empty_summary(), "config": cfg, "strategy_id": strategy_id}\n\n\ndef validate(cfg: dict) -> Optional[str]:\n    """Config guards — a wrong unit must ABORT, never run."""\n    block = _hhmm(cfg["entry_cutoff"], -1)\n    eod = _hhmm(cfg["eod_square_off"], -1)\n    if block < 0 or eod < 0:\n        return "entry_cutoff / eod_square_off must be HH:MM"\n    if not (SESSION_OPEN_MIN < block <= eod <= 15 * 60 + 29):\n        return (f"time order must be 09:15 < entry_cutoff {cfg[\'entry_cutoff\']} <= "\n                f"eod_square_off {cfg[\'eod_square_off\']} <= 15:29")\n    for k in ("spot_tf", "opt_tf"):\n        if not (1 <= cfg[k] <= 60):\n            return f"{k} must be 1..60 minutes"\n    if not (1 <= cfg["ema_fast"] < cfg["ema_slow"] <= 200):\n        return f"EMA periods need 1 <= fast ({cfg[\'ema_fast\']}) < slow ({cfg[\'ema_slow\']}) <= 200"\n    if cfg["sel_prem_max"] <= 0 or cfg["sel_prem_min"] >= cfg["sel_prem_max"]:\n        return f"premium band needs 0 <= min ({cfg[\'sel_prem_min\']:g}) < max ({cfg[\'sel_prem_max\']:g})"\n    if cfg["sl_pts"] >= cfg["sel_prem_max"]:\n        return f"sl_pts {cfg[\'sl_pts\']:g} is at/above the band top — a premium-point stop, not a %?"\n    if cfg["trail_on"] and cfg["trail_gap_pts"] <= 0:\n        return "trailing SL needs trail_gap_pts > 0"\n    # ── EMC_V1_BLACKOUT_20261011 ──\n    sf, st = cfg.get("arm_skip_from", ""), cfg.get("arm_skip_to", "")\n    if bool(sf) != bool(st):\n        return "arming blackout needs both \'from\' and \'to\' (or neither)"\n    if sf:\n        a, b = _hhmm(sf, -1), _hhmm(st, -1)\n        if a < 0 or b < 0:\n            return "arming blackout times must be HH:MM"\n        if not (SESSION_OPEN_MIN <= a < b <= 15 * 60 + 30):\n            return f"arming blackout needs 09:15 <= from ({sf}) < to ({st}) <= 15:30"\n    # ── EMC_SELL_20261012 ──\n    if cfg.get("leg_action") == "SELL":\n        if cfg["tp_pts"] > 0 and cfg["tp_pts"] >= cfg["sel_prem_min"]:\n            return (f"SELL: TP {cfg[\'tp_pts\']:g} pts is at/above the band bottom ₹{cfg[\'sel_prem_min\']:g} — the "\n                    "target would sit at or below zero premium (unreachable)")\n        if cfg.get("hedge_enabled") and cfg["hedge_max_premium"] <= 0:\n            return "SELL hedge needs hedge_max_premium > 0 (₹ cap for the protective wing)"\n        if cfg.get("hedge_enabled") and cfg["hedge_max_premium"] >= cfg["sel_prem_min"]:\n            return (f"hedge cap ₹{cfg[\'hedge_max_premium\']:g} reaches the sold band (≥ ₹{cfg[\'sel_prem_min\']:g}) — "\n                    "the wing could be the short itself or nearer the money")\n    elif cfg.get("hedge_enabled"):\n        return "hedge (protective wing) applies only to leg_action SELL"\n    if cfg["warmup_sessions"] > 30 or cfg["opt_warmup_sessions"] > 10:\n        return "warm-up too long (spot <= 30 sessions, option <= 10)"\n    if cfg["opt_min_bars"] and cfg["opt_min_bars"] > 400:\n        return "opt_min_bars must be <= 400"\n    return None\n\n\ndef option_warm_bars(src, sym: str, ds: int, sessions: int, tf: int) -> List[EmcBar]:\n    """R3: the contract\'s closed opt_tf bars from up to `sessions` earlier\n    sessions held in the corpus (per-session resample on the 09:15 grid)."""\n    if sessions <= 0:\n        return []\n    prior = src.warmup_candles_before(sym, ds, sessions * MIN_PER_SESSION)\n    by_day: Dict[date, list] = {}\n    for c in prior:\n        by_day.setdefault(_ist_date(c.ts), []).append(c)\n    out: List[EmcBar] = []\n    for d in sorted(by_day)[-sessions:]:\n        out.extend(resample_session(by_day[d], day_start_epoch=_day_start_epoch(d), tf_minutes=tf))\n    return out\n\n\ndef _impl(*, db_path, strategy_id, underlying, date_from, date_to,\n          config_override, progress_cb, cancel_cb) -> Dict:\n    from app.backtest.data.candle_source import CandleSource\n    from app.backtest.engine.expiry_calendar import expected_expiry_for_day\n    from app.backtest.charges.charges_model import charges_for_long_trade\n    from app.backtest.util.lot_sizes import resolve_lot\n    from app.utils.market_hours import is_trading_day\n    from app.event_bus.audit_logger import write_audit_log\n\n    cfg = _merge_cfg(config_override)\n    bad = validate(cfg)\n    if bad:\n        return _abort(cfg, strategy_id, bad)\n    index_lot = INDEX_LOTS.get(underlying.upper())\n    if index_lot is None:\n        return _abort(cfg, strategy_id, f"EMC_V1 is index-only; no lot constant for {underlying}.")\n    lot_size, lot_source = resolve_lot(underlying=underlying, is_stock=False, cfg_lot=cfg["lot_size"],\n                                       index_lot=index_lot, db_path=db_path)\n    if lot_size is None:\n        return _abort(cfg, strategy_id, f"no lot size for {underlying}")\n    qty = cfg["lots"] * lot_size\n    from app.backtest.engine.lot_compounding import LotCompounder as _LotComp   # ── LOT_COMP_20260924 ──\n    _comp = _LotComp(config_override, date_from, cfg["lots"])\n\n    stf, otf = cfg["spot_tf"], cfg["opt_tf"]\n    block_min = _hhmm(cfg["entry_cutoff"], 14 * 60 + 30)\n    eod_min = _hhmm(cfg["eod_square_off"], 15 * 60 + 15)\n    opt_min_bars = cfg["opt_min_bars"] or cfg["ema_slow"]\n\n    src = CandleSource(db_path)\n    conn = src._conn()\n\n    def spot_day(ds: int) -> list:\n        return [EmcBar(r["ts"], r["open"], r["high"], r["low"], r["close"])\n                for r in conn.execute(\n                    """SELECT ts, open, high, low, close FROM backtest_candles_1m\n                       WHERE underlying=? AND instrument_type=\'SPOT\'\n                         AND ts>=? AND ts<? ORDER BY ts""",\n                    (underlying, ds, ds + 86400))]\n\n    days: List[date] = []\n    d = date_from\n    while d <= date_to:\n        if is_trading_day(d):\n            days.append(d)\n        d += timedelta(days=1)\n\n    # ── R1: warm the spot EMA pair on sessions before date_from ──\n    spot_pair = EmaPair(cfg["ema_fast"], cfg["ema_slow"])\n    warm_days: List[date] = []\n    d, guard = date_from - timedelta(days=1), 0\n    while len(warm_days) < cfg["warmup_sessions"] and guard < 60:\n        if is_trading_day(d):\n            warm_days.append(d)\n        d -= timedelta(days=1)\n        guard += 1\n    warmup_bars = 0\n    for wd in reversed(warm_days):\n        for b in resample_session(spot_day(_day_start_epoch(wd)), day_start_epoch=_day_start_epoch(wd),\n                                  tf_minutes=stf):\n            spot_pair.update(b.close)\n            warmup_bars += 1\n\n    params = DayParams(\n        sel_lo=cfg["sel_prem_min"], sel_hi=cfg["sel_prem_max"], sel_pick=cfg["sel_pick"],\n        direction=cfg["direction"], intrabar=cfg["opt_check"] == "intrabar", opt_min_bars=opt_min_bars,\n        fill=cfg["fill_mode"], sl_pts=cfg["sl_pts"], tp_pts=cfg["tp_pts"], trail_on=cfg["trail_on"],\n        trail_trigger=cfg["trail_trigger_pts"], trail_gap=cfg["trail_gap_pts"], xover_exit=cfg["xover_exit"],\n        block_min=block_min, eod_min=eod_min, max_trades=cfg["max_trades_per_day"],\n        max_losses=cfg["max_losses_per_day"],\n        skip_from=_hhmm(cfg["arm_skip_from"], -1) if cfg["arm_skip_from"] else -1,   # ── EMC_V1_BLACKOUT_20261011 ──\n        skip_to=_hhmm(cfg["arm_skip_to"], -1) if cfg["arm_skip_to"] else -1,\n        sell=cfg["leg_action"] == "SELL")   # ── EMC_SELL_20261012 ──\n\n    trades: List[EMCTrade] = []\n    sim: dict = {}\n    diag = {\n        "days_total": len(days), "days_traded": 0, "days_no_spot": 0, "days_uncovered": 0,\n        "days_skipped_expiry": 0, "days_no_cross": 0,\n        "gap_crosses": 0, "gap_crosses_ignored": 0,   # ── EMC_V1_FIX1_20261011 ──\n        # ── DTE_LOT_MULT_20260911 ──\n        "dte_lot_mult": {str(k): v for k, v in cfg["dte_lot_mult"].items()},\n        "dte_skipped_days": 0, "dte_scaled_days": 0, "dte_unknown_days": 0,\n        "warmup_bars": warmup_bars, "spot_bars": 0,\n        "opt_min_bars": opt_min_bars, "opt_warm_bars_sum": 0, "opt_tracks": 0, "opt_tracks_cold": 0,\n        "sel_px_sum": 0.0, "entry_px_sum": 0.0, "wait_min_sum": 0,\n        "ce_entries": 0, "pe_entries": 0, "ce_net": 0.0, "pe_net": 0.0,\n        "entry_hour_hist": {},\n        "sl_exits": 0, "tsl_exits": 0, "tp_exits": 0, "xover_exits": 0, "eod_exits": 0,\n        "sl_pnl": 0.0, "tsl_pnl": 0.0, "tp_pnl": 0.0, "xover_pnl": 0.0, "eod_pnl": 0.0,\n        # ── EMC_CARRY_20261012 ──\n        "run_end_exits": 0, "run_end_pnl": 0.0, "carried_trades": 0, "carried_pnl": 0.0,\n        "carry_no_data_days": 0, "carry_managed_skip_days": 0,\n        # ── EMC_SELL_20261012 ── leg action / wing economics (VET names)\n        "leg_action": cfg["leg_action"], "hedge_enabled": cfg["hedge_enabled"],\n        "hedge_max_premium": cfg["hedge_max_premium"], "hedge_synth_enabled": cfg["hedge_synth_enabled"],\n        "hedge_real": 0, "hedge_synth": 0, "hedge_synth_fail": 0, "hedge_stale_fills": 0,\n        "no_hedge_entries": 0, "hedge_exits": 0, "hedge_cost_total": 0.0, "hedge_synth_exits": 0,\n        "hedge_synth_pnl_gross": 0.0, "hedge_synth_mark_fallbacks": 0, "hedge_entry_px_sum": 0.0,\n        "hold_sum": 0, "trail_armed_trades": 0,\n        "underlying": underlying, "lot_size": lot_size, "lot_source": lot_source, "qty": qty,\n        "corpus_db": str(db_path).rsplit("/", 1)[-1],\n    }\n\n    # ── DTE_LOT_MULT_20260911 ── corpus trading-day calendar (sessions)\n    _dte_cal: List[str] = []\n    if cfg["dte_lot_mult"]:\n        from app.backtest.repo.trading_calendar import trading_dates as _td\n        _dte_cal = _td(underlying, db_path)\n        if not _dte_cal:\n            write_audit_log(f"[BACKTEST][{strategy_id}] dte_lot_mult set but the "\n                            f"corpus calendar is empty — multiplier ignored")\n    from app.backtest.engine.dte_lots import lots_for_day as _lots_for_day, dte_for_day as _dte_for_day\n\n    # ── EMC_SELL_20261012 ── leg action + wing (VET V1\'s rule, the IC synthetic primitives verbatim)\n    is_sell = cfg["leg_action"] == "SELL"\n    hedge_on = is_sell and bool(cfg["hedge_enabled"])\n    from app.backtest.charges.charges_model import charges_for_short_trade\n    if hedge_on:\n        from app.backtest.ic.backtest_ic_runner import _minute_ladder, _synth_leg_at, _synth_mark_at\n    wings: Dict[tuple, dict] = {}            # (entry day start, short sym, entry minute) → wing\n\n    def _leg_charges(entry: float, exitp: float, q: int, short: bool) -> float:\n        fn = charges_for_short_trade if short else charges_for_long_trade\n        return fn(entry_price=entry, exit_price=exitp, qty=q).total_charges\n\n    carry_on = bool(cfg["carry_overnight"])   # ── EMC_CARRY_20261012 ──\n    carry_pos: Optional[dict] = None           # position dict carried into the next session\n    carry_exp: Dict[str, str] = {}             # carried symbol → its expiry (ISO)\n    carry_last: Optional[tuple] = None         # (day_start, minute) of the carried position\'s last mark\n    import dataclasses as _dc\n    params_no_entry = _dc.replace(params, block_min=SESSION_OPEN_MIN)\n\n    for i, day in enumerate(days):\n        if cancel_cb and cancel_cb():\n            break\n        if progress_cb:\n            progress_cb({"day": i + 1, "total_days": len(days), "date": day.isoformat(),\n                         "trades": len(trades)})\n        ds = _day_start_epoch(day)\n        want = expected_expiry_for_day(day).isoformat()\n        spot_1m = spot_day(ds)\n        if not spot_1m:\n            diag["days_no_spot"] += 1\n            if carry_pos is not None:\n                diag["carry_no_data_days"] += 1\n            continue\n        spot_by_min = {(b.ts - ds) // 60: b for b in spot_1m}\n        bars_tf = resample_session(spot_1m, day_start_epoch=ds, tf_minutes=stf)\n        diag["spot_bars"] += len(bars_tf)\n        cross_at = spot_crosses(bars_tf, spot_pair)       # R1: ALWAYS advances\n        # ── EMC_V1_FIX1_20261011 ── first-candle (overnight-gap) cross\n        if bars_tf and (bars_tf[0].ts - ds) // 60 == SESSION_OPEN_MIN and bars_tf[0].end_min in cross_at:\n            diag["gap_crosses"] += 1\n            if not cfg["first_candle_cross"]:\n                del cross_at[bars_tf[0].end_min]\n                diag["gap_crosses_ignored"] += 1\n\n        entries_ok = True                          # ── EMC_CARRY_20261012 ── False = manage a carry only\n        if cfg["skip_expiry_day"] and date.fromisoformat(want) == day:\n            diag["days_skipped_expiry"] += 1\n            if carry_pos is None:\n                continue\n            entries_ok = False\n        day_qty = qty\n        if cfg["dte_lot_mult"]:\n            _dte = _dte_for_day(_dte_cal, day.isoformat(), want) if _dte_cal else None\n            _lots, _tag = _lots_for_day(cfg["lots"], cfg["dte_lot_mult"], _dte)\n            if _tag == "skip":\n                diag["dte_skipped_days"] += 1\n                if carry_pos is None:\n                    continue\n                entries_ok = False\n            if _tag == "scaled":\n                diag["dte_scaled_days"] += 1\n            elif _tag == "unknown":\n                diag["dte_unknown_days"] += 1\n            day_qty = _lots * lot_size\n        _comp.begin_day(day, trades)   # ── LOT_COMP_EQ_20260924 ── equity mode re-sizes from realised net\n        if _comp.on:   # ── LOT_COMP_20260924 ── today\'s qty (on top of DTE)\n            day_qty = _comp.scale_qty(day_qty, lot_size, day)\n\n        if not any(k < eod_min for k in cross_at):\n            diag["days_no_cross"] += 1\n            if carry_pos is None:\n                continue\n            entries_ok = False\n        if not entries_ok:\n            diag["carry_managed_skip_days"] += 1\n\n        universe_cache: dict = {}\n        bars_cache: Dict[str, Dict[int, object]] = {}\n\n        def universe() -> List[dict]:\n            if "u" not in universe_cache:\n                universe_cache["u"] = src.contracts_active_on_day(underlying, ds, expiry=want)\n            return universe_cache["u"]\n\n        def bars_of(sym: str) -> Dict[int, object]:\n            if sym not in bars_cache:\n                bars_cache[sym] = {(c.ts - ds) // 60: c for c in src.candles_1m_for_symbol_day(sym, ds)}\n            return bars_cache[sym]\n\n        def quotes_at(k: int, side: str) -> List[dict]:\n            out = []\n            for c in universe():\n                if c.get("instrument_type") != side or c.get("strike") is None:\n                    continue\n                bm = bars_of(c["tradingsymbol"])\n                px = None\n                for m in range(k, k - stf, -1):        # E4: close at k, else last print in the spot bar\n                    b = bm.get(m)\n                    if b is not None and b.close:\n                        px = float(b.close)\n                        break\n                if px is not None:\n                    out.append({"sym": c["tradingsymbol"], "strike": float(c["strike"]), "price": px,\n                                "expiry": c.get("expiry")})\n            return out\n\n        def track_of(c: dict) -> OptionEmaTrack:\n            warm = option_warm_bars(src, c["sym"], ds, cfg["opt_warmup_sessions"], otf)\n            diag["opt_tracks"] += 1\n            diag["opt_warm_bars_sum"] += len(warm)\n            if not warm:\n                diag["opt_tracks_cold"] += 1\n            today = src.candles_1m_for_symbol_day(c["sym"], ds)\n            return OptionEmaTrack(fast=cfg["ema_fast"], slow=cfg["ema_slow"], tf=otf, ds=ds,\n                                  warm_bars=warm, today_1m=today)\n\n        def spot_at(k: int) -> Optional[float]:\n            b = spot_by_min.get(k)\n            return float(b.close) if b is not None else None\n\n        def net_of(entry: float, exitp: float, q: Optional[int] = None) -> float:\n            q = day_qty if q is None else q            # ── EMC_CARRY_20261012 ── a carried trade passes its own qty\n            ch = charges_for_long_trade(entry_price=entry, exit_price=exitp, qty=q).total_charges\n            return round((exitp - entry) * q - ch, 2)\n\n        # ── EMC_SELL_20261012 ── wing helpers for THIS session\n        closes_cache: Dict[str, Dict[int, float]] = {}\n\n        def _closes(sym: str) -> Dict[int, float]:\n            m = closes_cache.get(sym)\n            if m is None:\n                m = {c.ts: float(c.close) for c in src.candles_1m_for_symbol_day(sym, ds)}\n                closes_cache[sym] = m\n            return m\n\n        def _px_at_or_before(sym: str, ts: int):\n            mm = _closes(sym)\n            if ts in mm:\n                return mm[ts], False\n            older = [t_ for t_ in mm if t_ <= ts]\n            if not older:\n                return None, False\n            return mm[max(older)], True\n\n        def _expiry_ts(exp_iso: str) -> int:\n            d_ = date.fromisoformat(str(exp_iso))\n            return _day_start_epoch(d_) + 15 * 3600 + 30 * 60\n\n        def _week(exp_iso: str) -> list:\n            if str(exp_iso) == want:\n                return universe()\n            return src.contracts_active_on_day(underlying, ds, expiry=str(exp_iso))\n\n        def _select_wing(side: str, short_sym: str, ts: int, exp_iso: str) -> Optional[dict]:\n            best = None\n            for c in _week(exp_iso):\n                if c.get("instrument_type") != side or c["tradingsymbol"] == short_sym:\n                    continue\n                px, stale = _px_at_or_before(c["tradingsymbol"], ts)\n                if px is None or px <= 0 or px > cfg["hedge_max_premium"]:\n                    continue\n                if best is None or px > best["px"]:\n                    best = {"sym": c["tradingsymbol"], "px": float(px), "stale": stale,\n                            "strike": float(c.get("strike") or 0), "synth": False}\n            if best is not None:\n                diag["hedge_real"] += 1\n                if best["stale"]:\n                    diag["hedge_stale_fills"] += 1\n                return best\n            if not cfg["hedge_synth_enabled"]:\n                return None\n            wk = _week(exp_iso)\n            meta = {c["tradingsymbol"]: {"strike": c.get("strike")} for c in wk}\n            try:\n                spec, reason = _synth_leg_at(src=src, week=wk, meta_by_sym=meta, day_start=ds, ts=ts,\n                                             expiry_ts=_expiry_ts(exp_iso), opt_type=side,\n                                             cap=cfg["hedge_max_premium"], underlying=underlying,\n                                             want_expiry=str(exp_iso), skew_mult=cfg["hedge_skew_mult"],\n                                             ladder=_minute_ladder(src, wk, ds, ts))\n            except Exception:\n                spec, reason = None, "error"\n            if spec is None:\n                diag["hedge_synth_fail"] += 1\n                return None\n            diag["hedge_synth"] += 1\n            return {"sym": spec["symbol"], "px": float(spec["price"]), "stale": False,\n                    "strike": float(spec["strike"]), "synth": True}\n\n        def _mark_wing(w: dict, ts: int) -> float:\n            """Wing exit price at `ts` this session — model if modelled in, a\n            real print otherwise (never mixed); last mark when neither exists."""\n            px = None\n            if w["synth"]:\n                wk = _week(w["expiry"])\n                try:\n                    px = _synth_mark_at(src=src, week=wk, meta_by_sym={c["tradingsymbol"]: {"strike": c.get("strike")}\n                                                                       for c in wk},\n                                        day_start=ds, ts=ts, expiry_ts=_expiry_ts(w["expiry"]), opt_type=w["side"],\n                                        strike=w["strike"], skew_mult=cfg["hedge_skew_mult"])\n                except Exception:\n                    px = None\n            else:\n                px, stale = _px_at_or_before(w["sym"], ts)\n                if px is not None and stale:\n                    diag["hedge_stale_fills"] += 1\n            if px is None or px <= 0:\n                diag["hedge_synth_mark_fallbacks"] += 1 if w["synth"] else 0\n                px = w.get("last", w["px"])\n            w["last"] = float(px)\n            return float(px)\n\n        def entry_hook(sym: str, kmin: int, px: float) -> bool:\n            if not hedge_on:\n                return True\n            side_ = "CE" if sym.endswith("CE") else "PE"\n            exp_iso = next((str(c.get("expiry")) for c in universe() if c["tradingsymbol"] == sym), want)\n            w = _select_wing(side_, sym, ds + kmin * 60, exp_iso)\n            if w is None:\n                diag["no_hedge_entries"] += 1\n                return False\n            w.update(side=side_, expiry=exp_iso, qty=day_qty)\n            wings[(ds, sym, kmin)] = w\n            return True\n\n        def pair_pnl(t, exit_px: float, k_exit: int):\n            """→ (gross, charges, wing or None, wing exit px) for a position\n            closed at k_exit THIS session — the trade row and the loss cap\n            use this one function."""\n            q = t.qty if t.qty is not None else day_qty\n            if t.sell:\n                gross = (t.entry_px - exit_px) * q\n                ch = _leg_charges(t.entry_px, exit_px, q, True)\n            else:\n                gross = (exit_px - t.entry_px) * q\n                ch = _leg_charges(t.entry_px, exit_px, q, False)\n            w = wings.get((t.entry_ds if t.entry_ds is not None else ds, t.sym, t.entry_min))\n            wx = None\n            if w is not None:\n                wx = _mark_wing(w, ds + min(k_exit, SESSION_LAST_MIN) * 60)\n                gross += (wx - w["px"]) * q\n                ch += _leg_charges(w["px"], wx, q, False)\n            return gross, ch, w, wx\n\n        trade_net = None\n        if is_sell:\n            def trade_net(t, exit_px, k_exit):\n                g, c_, _w, _wx = pair_pnl(t, exit_px, k_exit)\n                return round(g - c_, 2)\n\n        carry = None\n        if carry_on:                                   # ── EMC_CARRY_20261012 ──\n            def carry_ok(t, _d=day.isoformat(), _want=want):\n                exp = carry_exp.get(t.sym)\n                if exp is None:\n                    exp = next((str(c.get("expiry")) for c in universe() if c["tradingsymbol"] == t.sym), _want)\n                return str(exp) > _d                   # never carry on the contract\'s own expiry day\n            carry = {"in": carry_pos, "ok": carry_ok}\n        before = sim.get("setup_no_universe", 0)\n        day_trades = simulate_day(p=params if entries_ok else params_no_entry, cross_at=cross_at,\n                                  quotes_at=quotes_at, bars_of=bars_of, track_of=track_of, net_of=net_of,\n                                  spot_at=spot_at, diag=sim, carry=carry,\n                                  trade_net=trade_net, entry_hook=entry_hook if hedge_on else None)   # ── EMC_SELL_20261012 ──\n        if carry is not None:                          # ── EMC_CARRY_20261012 ──\n            out = carry.get("out")\n            if out is not None:\n                ct = out["t"]\n                if ct.qty is None:\n                    ct.qty = day_qty\n                if ct.entry_ds is None:\n                    ct.entry_ds = ds\n                if ct.sym not in carry_exp:\n                    carry_exp[ct.sym] = next((str(c.get("expiry")) for c in universe()\n                                              if c["tradingsymbol"] == ct.sym), want)\n                ct.nights += 1\n                carry_last = (ds, SESSION_LAST_MIN)\n            carry_pos = out\n        if sim.get("setup_no_universe", 0) > before and not universe():\n            diag["days_uncovered"] += 1\n        if day_trades:\n            diag["days_traded"] += 1\n        exp_of = {c["tradingsymbol"]: c.get("expiry") for c in universe_cache.get("u", [])}\n        for dt in day_trades:\n            tq = dt.qty if dt.qty is not None else day_qty            # ── EMC_CARRY_20261012 ──\n            eds = dt.entry_ds if dt.entry_ds is not None else ds\n            texp = carry_exp.pop(dt.sym, None) if dt.nights else None\n            if is_sell:                                # ── EMC_SELL_20261012 ── the pair, as the loss cap saw it\n                gross, ch, wing, wing_x = pair_pnl(dt, dt.exit_px, dt.exit_min)\n                if wing is not None:\n                    w_net = (wing_x - wing["px"]) * tq - _leg_charges(wing["px"], wing_x, tq, False)\n                    diag["hedge_exits"] += 1\n                    diag["hedge_cost_total"] += round(w_net, 2)\n                    diag["hedge_entry_px_sum"] += wing["px"]\n                    if wing["synth"]:\n                        diag["hedge_synth_exits"] += 1\n                        diag["hedge_synth_pnl_gross"] += round((wing_x - wing["px"]) * tq, 2)\n                    wings.pop((dt.entry_ds if dt.entry_ds is not None else ds, dt.sym, dt.entry_min), None)\n            else:\n                wing = None\n                gross = (dt.exit_px - dt.entry_px) * tq\n                ch = charges_for_long_trade(entry_price=dt.entry_px, exit_price=dt.exit_px,\n                                            qty=tq).total_charges\n            net = gross - ch\n            hh, mm = dt.entry_min // 60, dt.entry_min % 60\n            sl_tag = f"SL{cfg[\'sl_pts\']:g}" if cfg["sl_pts"] > 0 else "SLoff"\n            tp_tag = f"TP{cfg[\'tp_pts\']:g}" if cfg["tp_pts"] > 0 else "TPoff"\n            tr_tag = f"·TSL{cfg[\'trail_trigger_pts\']:g}/{cfg[\'trail_gap_pts\']:g}" if cfg["trail_on"] else ""\n            wait_tag = "aligned" if dt.aligned_at_setup else f"wait{dt.waited}m"\n            arm_tag = f"arm{dt.sel_min // 60:02d}:{dt.sel_min % 60:02d}"   # ── EMC_V1_FIX1_20261011 ── the arming spot cross (its candle\'s last minute)\n            carry_tag = f"·carry{dt.nights}n" if dt.nights else ""\n            if is_sell:                                # ── EMC_SELL_20261012 ──\n                carry_tag += "·SELL" + (f"·wing{(\'~\' if wing[\'synth\'] else \'\')}₹{wing[\'px\']:g}" if wing else "·naked")\n            t = EMCTrade(\n                tradingsymbol=dt.sym, symbol=dt.sym, instrument_type=dt.side, strike=dt.strike,\n                expiry=texp or exp_of.get(dt.sym, want), direction="SELL" if is_sell else "BUY",\n                entry_ts=eds + dt.entry_min * 60, entry_price=round(dt.entry_px, 2),\n                sl=dt.sl, tp=dt.tp, exit_ts=ds + dt.exit_min * 60, exit_price=round(dt.exit_px, 2),\n                exit_reason=dt.reason, qty=tq,\n                entry_spot=round(dt.entry_spot, 2) if dt.entry_spot is not None else None,\n                condition=(f"EMC·{dt.side}·{hh:02d}:{mm:02d}·{stf}m/{otf}m·EMA{cfg[\'ema_fast\']}/"\n                           f"{cfg[\'ema_slow\']}·sel₹{dt.sel_px:g}·{arm_tag}·{wait_tag}·{sl_tag}·{tp_tag}{tr_tag}{carry_tag}"))\n            t.pnl = t.gross = round(gross, 2)\n            t.charges = round(ch, 2)\n            t.net_pnl = t.net = round(net, 2)\n            t.max_adverse = round(dt.mae * tq, 2)\n            t.max_favorable = round(dt.mfe * tq, 2)\n            t.hold_min = max(1, (t.exit_ts - t.entry_ts) // 60)\n            if wing is not None:                       # ── EMC_SELL_20261012 ──\n                t.wing_symbol, t.wing_entry, t.wing_exit = wing["sym"], round(wing["px"], 2), round(wing_x, 2)\n                if wing["synth"]:                      # IC/VET convention: model-priced wing\n                    t.synthetic, t.synth_kind = True, "hedge"\n            trades.append(t)\n            if dt.nights:\n                diag["carried_trades"] += 1\n                diag["carried_pnl"] += round(net, 2)\n            key = dt.reason.lower()\n            diag[f"{key}_exits"] += 1\n            diag[f"{key}_pnl"] += round(net, 2)\n            diag["hold_sum"] += t.hold_min\n            diag["sel_px_sum"] += dt.sel_px\n            diag["entry_px_sum"] += dt.entry_px\n            diag["wait_min_sum"] += dt.waited\n            diag["trail_armed_trades"] += 1 if dt.trail_armed else 0\n            diag["ce_entries" if dt.side == "CE" else "pe_entries"] += 1\n            diag["ce_net" if dt.side == "CE" else "pe_net"] += round(net, 2)\n            hk = f"{hh:02d}"\n            diag["entry_hour_hist"][hk] = diag["entry_hour_hist"].get(hk, 0) + 1\n\n    if carry_pos is not None:                      # ── EMC_CARRY_20261012 ── open at the end of the run\n        ct = carry_pos["t"]\n        lds = carry_last[0] if carry_last else _day_start_epoch(days[-1])\n        px = float(carry_pos.get("last") or ct.entry_px)\n        tq = ct.qty or qty\n        if ct.sell:                                    # ── EMC_SELL_20261012 ── short + wing at their last marks\n            gross = (ct.entry_px - px) * tq\n            ch = _leg_charges(ct.entry_px, px, tq, True)\n            w = wings.get((ct.entry_ds, ct.sym, ct.entry_min))\n            if w is not None:\n                wx = float(w.get("last", w["px"]))\n                gross += (wx - w["px"]) * tq\n                ch += _leg_charges(w["px"], wx, tq, False)\n        else:\n            ch = charges_for_long_trade(entry_price=ct.entry_px, exit_price=px, qty=tq).total_charges\n            gross = (px - ct.entry_px) * tq\n        t = EMCTrade(tradingsymbol=ct.sym, symbol=ct.sym, instrument_type=ct.side, strike=ct.strike,\n                     expiry=carry_exp.get(ct.sym), direction=("SELL" if ct.sell else "BUY"),\n                     entry_ts=(ct.entry_ds or lds) + ct.entry_min * 60, entry_price=round(ct.entry_px, 2),\n                     sl=ct.sl, tp=ct.tp, exit_ts=lds + SESSION_LAST_MIN * 60, exit_price=round(px, 2),\n                     exit_reason="RUN_END", qty=tq,\n                     condition=f"EMC·{ct.side}·carry{ct.nights}n·open at the end of the run — closed at its last mark")\n        t.pnl = t.gross = round(gross, 2)\n        t.charges = round(ch, 2)\n        t.net_pnl = t.net = round(gross - ch, 2)\n        t.max_adverse = round(ct.mae * tq, 2)\n        t.max_favorable = round(ct.mfe * tq, 2)\n        t.hold_min = max(1, (t.exit_ts - t.entry_ts) // 60)\n        trades.append(t)\n        diag["run_end_exits"] += 1\n        diag["run_end_pnl"] += t.net_pnl\n        diag["carried_trades"] += 1\n        diag["carried_pnl"] += t.net_pnl\n    src.close()\n    for k, v in sim.items():\n        diag[k] = v\n    n = len(trades)\n    if n:\n        diag["avg_hold_min"] = round(diag["hold_sum"] / n, 1)\n        diag["avg_sel_px"] = round(diag["sel_px_sum"] / n, 2)\n        diag["avg_entry_px"] = round(diag["entry_px_sum"] / n, 2)\n        diag["avg_wait_min"] = round(diag["wait_min_sum"] / n, 1)\n    if diag["opt_tracks"]:\n        diag["avg_opt_warm_bars"] = round(diag["opt_warm_bars_sum"] / diag["opt_tracks"], 1)\n    for k in ("ce_net", "pe_net", "sl_pnl", "tsl_pnl", "tp_pnl", "xover_pnl", "eod_pnl", "sel_px_sum",\n              "entry_px_sum", "run_end_pnl", "carried_pnl"):\n        diag[k] = round(diag[k], 2)\n    summary = _summarize(trades, diag)\n    write_audit_log(\n        f"[BACKTEST][{strategy_id}] {underlying} {date_from}..{date_to}: "\n        f"{summary[\'total_trades\']} trades, net {summary[\'net_pnl\']:,.0f}, "\n        f"DD {summary[\'max_drawdown\']:,.0f}, exits SL {diag[\'sl_exits\']} / TSL {diag[\'tsl_exits\']} / "\n        f"TP {diag[\'tp_exits\']} / XOVER {diag[\'xover_exits\']} / EOD {diag[\'eod_exits\']}, "\n        f"setups {diag.get(\'setups\', 0)} (no band {diag.get(\'setup_no_band\', 0)})")\n    return {"run_id": str(uuid.uuid4()), "summary": summary, "config": cfg, "trades": trades,\n            "strategy_id": strategy_id}\n\n\ndef _summarize(trades: List[EMCTrade], diag: dict) -> dict:\n    closed = [t for t in trades if t.exit_price is not None]\n    if not closed:\n        s = _empty_summary()\n        s["diag_emc"] = diag\n        return s\n    eq = peak = mdd = 0.0\n    for t in sorted(closed, key=lambda x: (x.exit_ts or 0, x.entry_ts or 0)):\n        eq += t.net_pnl\n        peak = max(peak, eq)\n        mdd = max(mdd, peak - eq)\n    nets = [t.net_pnl for t in closed]\n    wins = sum(1 for v in nets if v > 0)\n    net = sum(nets)\n    if abs(net) > 1e-9:\n        for k in ("sl", "tsl", "tp", "xover", "eod"):\n            diag[f"{k}_pnl_share_pct"] = round(100.0 * diag[f"{k}_pnl"] / net, 1)\n    return {\n        "total_trades": len(closed), "wins": wins, "losses": sum(1 for v in nets if v < 0),\n        "win_rate": round(100.0 * wins / len(closed), 2),\n        "gross_pnl": round(sum(t.pnl for t in closed), 2),\n        "total_charges": round(sum(t.charges for t in closed), 2),\n        "net_pnl": round(net, 2), "max_drawdown": round(mdd, 2),\n        "ambiguous_fills": 0, "diag_emc": diag,\n    }\n')

REPLACE['backend/app/backtest/emc/test_emc_runner_sim.py'] = ('77b59a3cfbbe11e3e0cc4edf1c99529458672c8d1e007b3c31320560709f7d2f', '# backend/app/backtest/emc/test_emc_runner_sim.py\n#\n# ── EMC_V1_20261011 ── behavioural simulation suite (+ EMC_V1_FIX1_20261011: gap-cross\n# toggle, arm tag, independent crossover proof, replay arming marker;\n# EMC_V1_BLACKOUT_20261011: arming blackout window; EMC_CARRY_20261012: carry\n# overnight, backtest only; EMC_SELL_20261012: leg action SELL + protective wing). Standalone:\n#   cd backend && PYTHONPATH=$PWD python3 app/backtest/emc/test_emc_runner_sim.py\n# Part 1 pure engine (EMA = Pine ta.ema, crosses, band pick, fills, trail,\n# the option track vs a brute-force causal recompute). Part 2 scripted\n# sessions through simulate_day (every rule of the spec, one scenario each).\n# Part 3 the whole runner on the replay suite\'s synthetic Black-76 corpus:\n# fill / band / ordering / cap / cutoff invariants on every trade.\n\nfrom __future__ import annotations\n\nimport os\nimport random\nimport sys\nimport tempfile\nfrom datetime import date, datetime, timedelta\nfrom types import SimpleNamespace as NS\n\nHERE = os.path.dirname(os.path.abspath(__file__))\nBACKEND = os.path.abspath(os.path.join(HERE, "..", "..", ".."))\nsys.path.insert(0, HERE)\nsys.path.insert(0, BACKEND)\n\nfrom emc_v1_engine import (                       # noqa: E402\n    EmcBar, Ema, EmaPair, ema_series, crossed, aligned, spot_crosses, pick_in_band,\n    OptionEmaTrack, stop_fill, target_fill, effective_stop, DayParams, simulate_day,\n    resample_session, SESSION_OPEN_MIN)\n\nIST = 5 * 3600 + 30 * 60\nFAILS = []\nNPASS = [0]\n\n\ndef check(name: str, ok, note: str = "") -> None:\n    print(f"  {\'PASS\' if ok else \'FAIL\'}  {name}{(\'  — \' + str(note)) if (note and not ok) else \'\'}")\n    if ok:\n        NPASS[0] += 1\n    else:\n        FAILS.append(name)\n\n\ndef ds_for(d: date) -> int:\n    return int((datetime(d.year, d.month, d.day) - datetime(1970, 1, 1)).total_seconds()) - IST\n\n\nDS = ds_for(date(2026, 1, 5))\nO = SESSION_OPEN_MIN\n\n\ndef b1(minute, o, h, l, c, ds=DS):\n    return EmcBar(ds + minute * 60, o, h, l, c)\n\n\n# ═══════════════════════════════ 1. engine ═══════════════════════════════\nprint("── engine: EMA (Pine ta.ema, SMA seed) ──")\nvals = [10, 11, 12, 13, 14, 15, 16]\ne = ema_series(vals, 3)\ncheck("None until period values", e[0] is None and e[1] is None)\ncheck("period-th value is the SMA seed", abs(e[2] - 11.0) < 1e-12)\ncheck("recursive alpha 2/(n+1)", abs(e[3] - (13 * 0.5 + 11 * 0.5)) < 1e-12)\nem = Ema(3)\nem.update(10); em.update(11)\ncheck("peek before ready returns the seed it would make", abs(em.peek(12) - 11.0) < 1e-12 and em.value is None)\nem.update(12)\npk = em.peek(20)\ncheck("peek does not commit", abs(pk - (20 * 0.5 + 11 * 0.5)) < 1e-12 and abs(em.value - 11.0) < 1e-12)\n# parity with the fleet\'s TMA SMA-seeded EMA\ntry:\n    from app.backtest.tma.tma_v1_engine import ema_series as tma_ema\n    random.seed(3)\n    xs = [100 + random.uniform(-5, 5) for _ in range(300)]\n    a, b = ema_series(xs, 21), tma_ema(xs, 21)\n    check("bit-identical to TMA_V1\'s SMA-seeded EMA (300 values)",\n          all((p is None and q is None) or (p is not None and q is not None and abs(p - q) < 1e-9)\n              for p, q in zip(a, b)))\nexcept Exception as ex:   # pragma: no cover\n    check("TMA EMA parity (import)", False, repr(ex))\n\nprint("── engine: crosses / alignment ──")\ncheck("crossover", crossed(1, 2, 3, 2) == 1)\ncheck("crossover from equality", crossed(2, 2, 3, 2) == 1)\ncheck("crossunder", crossed(3, 2, 1, 2) == -1)\ncheck("no cross when staying above", crossed(3, 2, 4, 2) == 0)\ncheck("touch without crossing is not a cross", crossed(3, 2, 2, 2) == 0)\ncheck("None → 0", crossed(None, 2, 3, 2) == 0)\ncheck("aligned CE/PE", aligned("CE", 2, 1) and aligned("PE", 1, 2) and not aligned("CE", 1, 1) and not aligned("PE", None, 1))\npair = EmaPair(2, 3)\nbars = [EmcBar(DS + (O + 5 * i) * 60, 0, 0, 0, c, O + 5 * i + 4) for i, c in enumerate([10, 10, 10, 12, 14, 9, 7, 7])]\nxs = spot_crosses(bars, pair)\ncheck("spot_crosses keyed by bar end minute, both directions",\n      list(xs.values()) == [1, -1] and all((k - O + 1) % 5 == 0 for k in xs), str(xs))\np2 = EmaPair(2, 3)\nx1 = spot_crosses(bars[:4], p2)\nx2 = spot_crosses(bars[4:], p2)\ncheck("continuous across sessions (split == whole)", {**x1, **x2} == xs)\n\nprint("── engine: band pick ──")\nqs = [{"sym": "A", "strike": 23000, "price": 210}, {"sym": "B", "strike": 23050, "price": 195.5},\n      {"sym": "C", "strike": 23100, "price": 168}, {"sym": "D", "strike": 23150, "price": 150},\n      {"sym": "E", "strike": 23200, "price": 149.95}]\ncheck("highest premium inside [150,200]", pick_in_band(qs, 150, 200)["sym"] == "B")\ncheck("band is inclusive at both ends", pick_in_band(qs, 150, 195.5)["sym"] == "B" and\n      pick_in_band(qs, 150, 150)["sym"] == "D")\ncheck("lowest pick", pick_in_band(qs, 150, 200, pick="lowest")["sym"] == "D")\ncheck("nothing in band → None", pick_in_band(qs, 300, 400) is None)\ntie = [{"sym": "X", "strike": 23000, "price": 180}, {"sym": "Y", "strike": 23100, "price": 180}]\ncheck("tie → strike nearer spot", pick_in_band(tie, 150, 200, spot=23090)["sym"] == "Y")\n\nprint("── engine: fills / trail ──")\nB = NS(open=100, high=110, low=90, close=105)\ncheck("stop touched books AT level", stop_fill(95, B) == 95)\ncheck("stop gapped books the open", stop_fill(101, B) == 100)\ncheck("stop not reached", stop_fill(89, B) is None)\ncheck("target touched books AT level", target_fill(108, B) == 108)\ncheck("target gapped books the open", target_fill(99, B) == 100)\ncheck("trail not armed below trigger", effective_stop(entry=100, peak=115, sl_level=80, trail_on=True,\n                                                      trail_trigger=20, trail_gap=10) == (80, False))\ncheck("trail armed at trigger: peak − gap", effective_stop(entry=100, peak=120, sl_level=80, trail_on=True,\n                                                           trail_trigger=20, trail_gap=10) == (110, True))\ncheck("trail never below fixed SL", effective_stop(entry=100, peak=100, sl_level=80, trail_on=True,\n                                                   trail_trigger=0, trail_gap=30) == (80, False))\ncheck("trail with SL off", effective_stop(entry=100, peak=105, sl_level=None, trail_on=True,\n                                          trail_trigger=0, trail_gap=10) == (95, True))\n\nprint("── engine: option track vs brute-force causal recompute ──")\nrandom.seed(11)\npx = 180.0\nwarm_1m, today_1m = [], []\nDSW = ds_for(date(2026, 1, 2))\nfor m in range(O, O + 375):\n    o = px; px = max(5, px + random.uniform(-2, 2))\n    warm_1m.append(EmcBar(DSW + m * 60, o, max(o, px) + 0.5, min(o, px) - 0.5, px))\nfor m in range(O, O + 375):\n    if random.random() < 0.07:                # missing prints\n        continue\n    o = px; px = max(5, px + random.uniform(-2, 2))\n    today_1m.append(EmcBar(DS + m * 60, o, max(o, px) + 0.5, min(o, px) - 0.5, px))\nwarm = resample_session(warm_1m, day_start_epoch=DSW, tf_minutes=5)\ntr = OptionEmaTrack(fast=9, slow=21, tf=5, ds=DS, warm_bars=warm, today_1m=today_1m)\ntr2 = OptionEmaTrack(fast=9, slow=21, tf=5, ds=DS, warm_bars=warm, today_1m=today_1m)\nok_i = ok_c = True\nfor k in range(O, O + 375):\n    known = [c for c in today_1m if (c.ts - DS) // 60 <= k]\n    tb = resample_session(known, day_start_epoch=DS, tf_minutes=5)   # last bar = forming (partial) when k isn\'t an end\n    closes_i = [b.close for b in warm] + [b.close for b in tb]\n    closes_c = [b.close for b in warm] + [b.close for b in tb if b.end_min <= k]\n    fi, si, ni = tr.at(k, True)\n    fc, sc, nc = tr2.at(k, False)\n    rf, rs = ema_series(closes_i, 9)[-1], ema_series(closes_i, 21)[-1]\n    cf, cs = ema_series(closes_c, 9)[-1], ema_series(closes_c, 21)[-1]\n    if abs(fi - rf) > 1e-9 or abs(si - rs) > 1e-9 or ni != len(closes_i):\n        ok_i = False\n    if abs(fc - cf) > 1e-9 or abs(sc - cs) > 1e-9 or nc != len(closes_c):\n        ok_c = False\ncheck("intrabar: every minute equals EMA over closed bars + the forming bar\'s latest print", ok_i)\ncheck("bar_close: every minute equals EMA over closed bars only", ok_c)\ncold = OptionEmaTrack(fast=9, slow=21, tf=5, ds=DS, warm_bars=[], today_1m=today_1m)\nf, s, n = cold.at(O + 30, True)\ncheck("cold contract: slow EMA not ready after 7 bars", s is None and n <= 7)\ntry:\n    cold.at(O + 10)\n    back = False\nexcept ValueError:\n    back = True\ncheck("track refuses to go backwards in time (no accidental lookahead)", back)\n\n# ═══════════════════════════ 2. scripted sessions ═══════════════════════════\nprint("── simulate_day: scripted sessions ──")\n\n\nclass FakeTrack:\n    """Scripted option EMA: aligned (for its side) from minute `from_k` on."""\n    def __init__(self, side, from_k, ready_k=None):\n        self.side, self.from_k, self.ready_k = side, from_k, ready_k\n\n    def at(self, k, intrabar=True):\n        if self.ready_k is not None and k < self.ready_k:\n            return None, None, 5\n        up = k >= self.from_k\n        if self.side == "CE":\n            return (2.0, 1.0, 30) if up else (1.0, 2.0, 30)\n        return (1.0, 2.0, 30) if up else (2.0, 1.0, 30)\n\n\ndef flat_bars(price_by_min, hl=1.0):\n    """{min: bar} from {min: close}; open = previous close."""\n    out, prev = {}, None\n    for m in sorted(price_by_min):\n        v = price_by_min[m]\n        if isinstance(v, tuple):                 # explicit (o, h, l, c)\n            out[m] = NS(open=v[0], high=v[1], low=v[2], close=v[3])\n            prev = v[3]\n            continue\n        c = v\n        o = prev if prev is not None else c\n        out[m] = NS(open=o, high=max(o, c) + hl, low=min(o, c) - hl, close=c)\n        prev = c\n    return out\n\n\ndef P(**kw):\n    base = dict(sel_lo=150, sel_hi=200, sel_pick="highest", direction="BOTH", intrabar=True, opt_min_bars=21,\n                fill="close", sl_pts=20, tp_pts=40, trail_on=False, trail_trigger=20, trail_gap=15,\n                xover_exit=True, block_min=14 * 60 + 30, eod_min=15 * 60 + 15, max_trades=0, max_losses=0)\n    base.update(kw)\n    return DayParams(**base)\n\n\ndef run(p, cross_at, chain, tracks, net=None):\n    """chain: {sym: (side, strike, {min: close})}; tracks: {sym: FakeTrack}."""\n    bars = {s: flat_bars(v[2]) for s, v in chain.items()}\n\n    def quotes_at(k, side):\n        return [{"sym": s, "strike": v[1], "price": bars[s][k].close} for s, v in chain.items()\n                if v[0] == side and k in bars[s]]\n\n    dg = {}\n    tr = simulate_day(p=p, cross_at=cross_at, quotes_at=quotes_at, bars_of=lambda s: bars.get(s, {}),\n                      track_of=lambda c: tracks[c["sym"]],\n                      net_of=net or (lambda a, b: (b - a) * 65 - 40), spot_at=lambda k: 23000.0, diag=dg)\n    return tr, dg\n\n\nM = lambda hh, mm: hh * 60 + mm            # noqa: E731\nALL = range(O, M(15, 30))\n\n\ndef const(v, **over):\n    d = {m: v for m in ALL}\n    d.update(over)\n    return d\n\n\n# S1: up cross 10:04 → highest CE in band; option already aligned → entry at once (close fill)\nchain = {"CE1": ("CE", 23000, const(230)), "CE2": ("CE", 23050, const(190)), "CE3": ("CE", 23100, const(160)),\n         "PE1": ("PE", 23000, const(175))}\ntr, dg = run(P(), {M(10, 4): 1}, chain, {"CE2": FakeTrack("CE", 0)})\nt = tr[0] if tr else None\ncheck("S1 picks the highest CE premium in [150,200]", t and t.sym == "CE2" and t.side == "CE", tr)\ncheck("S1 already aligned → entry at the cross minute\'s close", t and t.entry_min == M(10, 4) and t.aligned_at_setup and t.entry_px == 190)\ncheck("S1 flat premium → EOD exit at the open of 15:15", t and t.reason == "EOD" and t.exit_min == M(15, 15))\n\n# S2: not aligned at setup → waits; option EMA aligns at 10:21 → entry 10:21 (close) / 10:22 open (next_open)\nce = const(180)\nce.update({M(10, 21): 184, M(10, 22): 186})\nchain = {"CE2": ("CE", 23050, ce)}\ntr, dg = run(P(), {M(10, 4): 1}, chain, {"CE2": FakeTrack("CE", M(10, 21))})\ncheck("S2 waits for the option\'s own EMA alignment, then buys (close fill)",\n      tr and tr[0].entry_min == M(10, 21) and tr[0].entry_px == 184 and tr[0].waited == 17 and not tr[0].aligned_at_setup, tr)\ntr, dg = run(P(fill="next_open"), {M(10, 4): 1}, chain, {"CE2": FakeTrack("CE", M(10, 21))})\ncheck("S2 next_open fill = the next minute\'s open", tr and tr[0].entry_min == M(10, 22) and tr[0].entry_px == 184, tr)\n\n# S3: SL / TP on premium points, pessimistic order\nce = const(180)\nce.update({M(10, 30): 158, M(10, 31): 150})           # bar 10:30 low = 157 → SL 160 touched\nchain = {"CE2": ("CE", 23050, ce)}\ntr, _ = run(P(), {M(10, 4): 1}, chain, {"CE2": FakeTrack("CE", 0)})\ncheck("S3 SL = entry − sl_pts, books AT the level", tr and tr[0].reason == "SL" and tr[0].exit_px == 160 and tr[0].exit_min == M(10, 30), tr)\nce = const(180)\nce.update({M(11, 0): 221})\ntr, _ = run(P(), {M(10, 4): 1}, {"CE2": ("CE", 23050, ce)}, {"CE2": FakeTrack("CE", 0)})\ncheck("S3 TP = entry + tp_pts, books AT the level", tr and tr[0].reason == "TP" and tr[0].exit_px == 220, tr)\nce = const(180)\nce[M(11, 0)] = (180, 190, 170, 182)                     # touches 176 AND 184\ntr, _ = run(P(sl_pts=4, tp_pts=4), {M(10, 4): 1}, {"CE2": ("CE", 23050, ce)}, {"CE2": FakeTrack("CE", 0)})\ncheck("S3 bar touching both → stop first (pessimistic)", tr and tr[0].reason == "SL" and tr[0].exit_min == M(11, 0)\n      and tr[0].exit_px == 176, tr)\nce = const(180)\nce[M(11, 0)] = (150, 152, 149, 151)                     # gaps through the stop at the open\ntr, _ = run(P(), {M(10, 4): 1}, {"CE2": ("CE", 23050, ce)}, {"CE2": FakeTrack("CE", 0)})\ncheck("S3 gap through the stop books the open (worse than the level)", tr and tr[0].exit_px == 150, tr)\n\n# S4: opposite spot cross exits (XOVER) and arms the other side in the same minute\nce, pe = const(180), const(170)\nce[M(11, 9)] = 190\nchain = {"CE2": ("CE", 23050, ce), "PE2": ("PE", 23000, pe)}\ntr, dg = run(P(tp_pts=0, sl_pts=0), {M(10, 4): 1, M(11, 9): -1}, chain,\n             {"CE2": FakeTrack("CE", 0), "PE2": FakeTrack("PE", 0)})\ncheck("S4 down cross exits the CE at that close (XOVER)", len(tr) >= 1 and tr[0].reason == "XOVER" and tr[0].exit_min == M(11, 9) and tr[0].exit_px == 190, tr)\ncheck("S4 …and buys the PE (already aligned) in the same minute", len(tr) == 2 and tr[1].side == "PE" and tr[1].entry_min == M(11, 9))\ntr, dg = run(P(tp_pts=0, sl_pts=0, xover_exit=False), {M(10, 4): 1, M(11, 9): -1}, chain,\n             {"CE2": FakeTrack("CE", 0), "PE2": FakeTrack("PE", 0)})\ncheck("S4 xover_exit off: CE held to EOD, PE signal dropped (one position at a time)",\n      len(tr) == 1 and tr[0].reason == "EOD" and dg.get("sig_dropped_open") == 1, (tr, dg))\n\n# S5: a pending setup is REPLACED by the opposite cross; expires at the cutoff\nchain = {"CE2": ("CE", 23050, const(180)), "PE2": ("PE", 23000, const(170))}\ntr, dg = run(P(), {M(10, 4): 1, M(10, 29): -1}, chain,\n             {"CE2": FakeTrack("CE", 10 ** 9), "PE2": FakeTrack("PE", M(10, 40))})\ncheck("S5 opposite cross replaces the unfilled CE setup; PE fills later",\n      len(tr) == 1 and tr[0].side == "PE" and tr[0].entry_min == M(10, 40) and dg.get("setups_replaced") == 1, (tr, dg))\ntr, dg = run(P(), {M(14, 9): 1}, {"CE2": ("CE", 23050, const(180))}, {"CE2": FakeTrack("CE", M(14, 30))})\ncheck("S5 option aligns at 14:30 → no entry (cutoff), setup expired", tr == [] and dg.get("setups_expired_cutoff") == 1, dg)\ntr, dg = run(P(), {M(14, 9): 1}, {"CE2": ("CE", 23050, const(180))}, {"CE2": FakeTrack("CE", M(14, 29))})\ncheck("S5 alignment on the 14:29 close is still in time", len(tr) == 1 and tr[0].entry_min == M(14, 29))\ntr, dg = run(P(), {M(14, 34): 1}, {"CE2": ("CE", 23050, const(180))}, {"CE2": FakeTrack("CE", 0)})\ncheck("S5 spot cross after the cutoff arms nothing", tr == [] and dg.get("sig_dropped_cutoff") == 1, dg)\n\n# S6: band / direction / warm-up\ntr, dg = run(P(), {M(10, 4): 1}, {"CE1": ("CE", 23000, const(240))}, {})\ncheck("S6 nothing in band → no setup (counted)", tr == [] and dg.get("setup_no_band") == 1, dg)\ntr, dg = run(P(direction="PE"), {M(10, 4): 1}, {"CE2": ("CE", 23050, const(180))}, {"CE2": FakeTrack("CE", 0)})\ncheck("S6 direction PE ignores up crosses", tr == [] and dg.get("sig_dropped_dir") == 1)\ntr, dg = run(P(), {M(9, 19): 1}, {"CE2": ("CE", 23050, const(180))}, {"CE2": FakeTrack("CE", 0, ready_k=M(10, 30))})\ncheck("S6 option EMA not ready → waits; enters once ready", len(tr) == 1 and tr[0].entry_min == M(10, 30)\n      and dg.get("entries_after_warmup_wait") == 1, (tr, dg))\n\n# S7: daily caps — max trades, max losing trades\ncrosses = {M(9, 29): 1, M(9, 49): -1, M(10, 9): 1, M(10, 29): -1, M(10, 49): 1}\nchain = {"CE2": ("CE", 23050, const(180)), "PE2": ("PE", 23000, const(170))}\ntks = {"CE2": FakeTrack("CE", 0), "PE2": FakeTrack("PE", 0)}\ntr, dg = run(P(max_trades=2), crosses, chain, tks)\ncheck("S7 max trades/day = 2", len(tr) == 2 and dg.get("sig_dropped_trades", 0) >= 1, (len(tr), dg))\ntr, dg = run(P(max_losses=2), crosses, chain, tks, net=lambda a, b: -100.0)\ncheck("S7 max losing trades/day = 2 halts new entries", len(tr) == 2 and dg.get("days_halted_losses") == 1\n      and dg.get("sig_dropped_losses", 0) >= 1, (len(tr), dg))\ntr, dg = run(P(max_losses=2), crosses, chain, tks, net=lambda a, b: 100.0)\ncheck("S7 winners do not count toward the losing cap", len(tr) == 5)\n\n# S8: trailing SL\nce = const(180)\nce.update({M(10, 10): 195, M(10, 11): 205, M(10, 12): 212, M(10, 13): 199, M(10, 14): 196})\ntr, _ = run(P(tp_pts=0, trail_on=True, trail_trigger=20, trail_gap=15), {M(10, 4): 1}, {"CE2": ("CE", 23050, ce)},\n            {"CE2": FakeTrack("CE", 0)})\n# peak through 10:12 = 213 (high = close+1) → stop 198; 10:13 bar low 198 → TSL @ 198\ncheck("S8 trailing stop arms at +trigger and books peak − gap", tr and tr[0].reason == "TSL" and tr[0].exit_px == 198\n      and tr[0].exit_min == M(10, 13), tr)\ntr, _ = run(P(tp_pts=0, trail_on=False), {M(10, 4): 1}, {"CE2": ("CE", 23050, ce)}, {"CE2": FakeTrack("CE", 0)})\ncheck("S8 same path without trail → held (EOD)", tr and tr[0].reason == "EOD")\nce2 = const(180)\nce2.update({M(10, 10): 230})                            # one bar: high 231 → the same bar\'s low must NOT hit a trail set by its own high\ntr, _ = run(P(tp_pts=0, trail_on=True, trail_trigger=20, trail_gap=15), {M(10, 4): 1}, {"CE2": ("CE", 23050, ce2)},\n            {"CE2": FakeTrack("CE", 0)})\ncheck("S8 trail uses the PREVIOUS bars\' peak (no same-bar high→low)", tr and tr[0].exit_min == M(10, 11) and tr[0].reason == "TSL", tr)\n\n# S9: EOD with a missing 15:15 bar → last mark; positions never cross the day\nce = {m: 180 for m in range(O, M(15, 12))}\ntr, dg = run(P(), {M(10, 4): 1}, {"CE2": ("CE", 23050, ce)}, {"CE2": FakeTrack("CE", 0)})\ncheck("S9 EOD at last mark when the square-off minute has no print", tr and tr[0].reason == "EOD" and tr[0].exit_px == 180\n      and dg.get("stale_marks", 0) >= 1, (tr, dg))\n\n# S10: arming blackout (EMC_V1_BLACKOUT_20261011)\nchain = {"CE2": ("CE", 23050, const(180)), "PE2": ("PE", 23000, const(170))}\ntks = {"CE2": FakeTrack("CE", 0), "PE2": FakeTrack("PE", 0)}\ntr, dg = run(P(skip_from=M(9, 30), skip_to=M(10, 0)), {M(9, 44): 1}, chain, tks)\ncheck("S10 a cross closing inside the blackout arms nothing", tr == [] and dg.get("sig_dropped_blackout") == 1, (tr, dg))\ntr, dg = run(P(skip_from=M(9, 30), skip_to=M(10, 0)), {M(10, 4): 1}, chain, tks)\ncheck("S10 \'to\' is exclusive: the 10:04 close arms", len(tr) == 1 and tr[0].sel_min == M(10, 4))\ntr, dg = run(P(skip_from=M(9, 30), skip_to=M(10, 0)), {M(9, 29): 1}, chain, tks)\ncheck("S10 \'from\' is inclusive only for minutes ≥ from: the 09:29 close arms", len(tr) == 1)\ntr, dg = run(P(skip_from=M(9, 30), skip_to=M(10, 0), sl_pts=0, tp_pts=0), {M(9, 24): 1, M(9, 49): -1}, chain, tks)\ncheck("S10 a blacked-out opposite cross still exits the open position (XOVER), arms no PE",\n      len(tr) == 1 and tr[0].reason == "XOVER" and tr[0].exit_min == M(9, 49) and dg.get("sig_dropped_blackout") == 1, (tr, dg))\ntr, dg = run(P(skip_from=M(9, 30), skip_to=M(10, 0)), {M(9, 24): 1, M(9, 49): -1}, chain,\n             {"CE2": FakeTrack("CE", 10 ** 9), "PE2": FakeTrack("PE", 0)})\ncheck("S10 a blacked-out opposite cross still cancels the pending setup", tr == [] and dg.get("setups_replaced") == 1, dg)\n\n# S11: leg action SELL (EMC_SELL_20261012)\nSP = lambda **kw: P(sell=True, **kw)                       # noqa: E731\nchain = {"CE2": ("CE", 23050, const(180)), "PE2": ("PE", 23000, const(170)), "PE1": ("PE", 22950, const(140))}\ntr, dg = run(SP(), {M(10, 4): 1}, chain, {"PE2": FakeTrack("PE", 0)})\ncheck("S11 SELL: an UP cross sells the PUT (highest in band), not the call",\n      tr and tr[0].side == "PE" and tr[0].sym == "PE2" and tr[0].sell, tr)\ncheck("S11 SELL: SL above / TP below the entry premium", tr and tr[0].sl == 190 and tr[0].tp == 130, tr)\ntr, _ = run(SP(), {M(10, 4): -1}, chain, {"CE2": FakeTrack("PE", 0)})\ncheck("S11 SELL: a DOWN cross sells the CALL", tr and tr[0].side == "CE" and tr[0].sym == "CE2")\ntr, _ = run(SP(), {M(10, 4): 1}, chain, {"PE2": FakeTrack("CE", 0)})\ncheck("S11 SELL: the sold option\'s own EMA must be FALLING (fast < slow) — rising premium never triggers", tr == [], tr)\ntr, _ = run(SP(), {M(10, 4): 1}, chain, {"PE2": FakeTrack("PE", M(10, 30))})\ncheck("S11 SELL: waits until the sold premium turns down", tr and tr[0].entry_min == M(10, 30) and not tr[0].aligned_at_setup)\npe = const(170)\npe[M(11, 0)] = (172, 192, 171, 185)                     # high 192 ≥ SL 190\ntr, _ = run(SP(), {M(10, 4): 1}, {"PE2": ("PE", 23000, pe)}, {"PE2": FakeTrack("PE", 0)})\ncheck("S11 SELL: stop on the bar HIGH, books AT the level", tr and tr[0].reason == "SL" and tr[0].exit_px == 190\n      and tr[0].exit_min == M(11, 0), tr)\npe = const(170)\npe[M(11, 0)] = (205, 210, 200, 202)                     # opens through the stop\ntr, _ = run(SP(), {M(10, 4): 1}, {"PE2": ("PE", 23000, pe)}, {"PE2": FakeTrack("PE", 0)})\ncheck("S11 SELL: a gap through the stop books the open (worse than the level)", tr and tr[0].exit_px == 205, tr)\npe = const(170)\npe[M(11, 0)] = (168, 169, 128, 131)                     # low 128 ≤ TP 130\ntr, _ = run(SP(), {M(10, 4): 1}, {"PE2": ("PE", 23000, pe)}, {"PE2": FakeTrack("PE", 0)})\ncheck("S11 SELL: target on the bar LOW, books AT the level", tr and tr[0].reason == "TP" and tr[0].exit_px == 130, tr)\npe = const(170)\npe[M(11, 0)] = (170, 195, 125, 170)                     # touches both\ntr, _ = run(SP(), {M(10, 4): 1}, {"PE2": ("PE", 23000, pe)}, {"PE2": FakeTrack("PE", 0)})\ncheck("S11 SELL: a bar touching both → stop first (pessimistic)", tr and tr[0].reason == "SL", tr)\ntr, dg = run(SP(sl_pts=0, tp_pts=0), {M(10, 4): 1, M(11, 9): -1}, {"PE2": ("PE", 23000, const(170)), "CE2": ("CE", 23050, const(180))},\n             {"PE2": FakeTrack("PE", 0), "CE2": FakeTrack("PE", 0)})\ncheck("S11 SELL: the opposite cross buys back the short PE and sells the CE", len(tr) == 2 and tr[0].reason == "XOVER"\n      and tr[0].side == "PE" and tr[1].side == "CE" and tr[1].entry_min == M(11, 9), tr)\npe = const(170)\npe.update({M(10, 10): 150, M(10, 11): 140, M(10, 12): 145, M(10, 13): 156})\ntr, _ = run(SP(tp_pts=0, trail_on=True, trail_trigger=20, trail_gap=15), {M(10, 4): 1}, {"PE2": ("PE", 23000, pe)},\n            {"PE2": FakeTrack("PE", 0)})\n# trough through 10:12 = 139 (low = close − 1) → stop 154; 10:13 bar high 157 → TSL @ 154\ncheck("S11 SELL: trailing stop follows the TROUGH (+gap), books AT it", tr and tr[0].reason == "TSL" and tr[0].exit_px == 154, tr)\ntr, _ = run(SP(direction="CE"), {M(10, 4): -1}, chain, {"CE2": FakeTrack("PE", 0)})\ncheck("S11 SELL: direction filter reads the CROSS (bullish only drops a down cross)", tr == [])\n\n# ═══════════════════════════ 3. runner on a corpus ═══════════════════════════\nprint("── runner: synthetic Black-76 corpus (replay suite generator) ──")\ntry:\n    from app.backtest.replay import replay_synth\n    from app.backtest.emc.backtest_emc_runner import run_emc_backtest, _merge_cfg, validate, DEFAULTS\n    APP = True\nexcept Exception as ex:   # pragma: no cover\n    APP = False\n    print(f"  SKIP  runner e2e (app tree unavailable: {ex!r})")\n\nif APP:\n    tmp = tempfile.mkdtemp(prefix="emc_sim_")\n    db = os.path.join(tmp, "backtest.db")\n    days = replay_synth.build(db, d0=date(2025, 1, 1), d1=date(2025, 2, 28), strikes_each_side=8, with_fut=False)\n    import sqlite3\n    from app.backtest.engine.expiry_calendar import expected_expiry_for_day\n\n    con = sqlite3.connect(db)\n    con.row_factory = sqlite3.Row\n\n    def opt_bar(sym, ts):\n        r = con.execute("SELECT open, high, low, close FROM backtest_candles_1m WHERE tradingsymbol=? AND ts=?",\n                        (sym, ts)).fetchone()\n        return r\n\n    def chain_close(day, side, ts):\n        exp = expected_expiry_for_day(day).isoformat()\n        return [(r["tradingsymbol"], r["close"]) for r in con.execute(\n            "SELECT tradingsymbol, close FROM backtest_candles_1m WHERE underlying=\'NIFTY\' AND instrument_type=? "\n            "AND expiry=? AND ts=?", (side, exp, ts))]\n\n    def IST_DATE(ts):\n        return (datetime(1970, 1, 1) + timedelta(seconds=ts + IST)).date()\n\n    base = {"sel_prem_min": 60, "sel_prem_max": 140}   # synthetic chain is cheaper than live NIFTY\n    progress = []\n    res = run_emc_backtest(db_path=db, strategy_id="EMC_V1", underlying="NIFTY", date_from=date(2025, 1, 15),\n                           date_to=date(2025, 2, 28), config_override=dict(base, fill_mode="close"),\n                           progress_cb=progress.append)\n    T = res["trades"]\n    dg = res["summary"].get("diag_emc", {})\n    check("runner produced trades on the synthetic corpus", len(T) >= 10, f"{len(T)} trades · {dg}")\n    check("progress callback per session", len(progress) == dg.get("days_total"))\n    ok_band = ok_hi = ok_ord = ok_time = ok_fill = ok_lvl = True\n    bad = []\n    for t in T:\n        d = IST_DATE(t.entry_ts)\n        sel = float(t.condition.split("sel₹")[1].split("·")[0])\n        if not (60 <= sel <= 140):\n            ok_band = False\n        # selection minute = entry minute − wait (close fill)\n        wait = 0 if "·aligned·" in t.condition else int(t.condition.split("·wait")[1].split("m")[0])\n        sel_ts = t.entry_ts - wait * 60\n        others = [c for s, c in chain_close(d, t.instrument_type, sel_ts) if 60 <= c <= 140]\n        if others and abs(max(others) - sel) > 1e-6:\n            ok_hi = False\n            bad.append((t.tradingsymbol, sel, max(others)))\n        if not (t.entry_ts < t.exit_ts or (t.exit_reason in ("SL", "TP", "TSL") and t.exit_ts > t.entry_ts)):\n            ok_ord = False\n        em = (t.entry_ts - ds_for(d)) // 60\n        xm = (t.exit_ts - ds_for(d)) // 60\n        if em >= 14 * 60 + 30 or xm > 15 * 60 + 15 or IST_DATE(t.exit_ts) != d:\n            ok_time = False\n        eb = opt_bar(t.tradingsymbol, t.entry_ts)\n        if eb is None or abs(eb["close"] - t.entry_price) > 0.011:\n            ok_fill = False\n        if t.exit_reason == "SL" and t.exit_price > t.entry_price - 20 + 0.011:\n            ok_lvl = False\n        if t.exit_reason == "TP" and t.exit_price < t.entry_price + 40 - 0.011:\n            ok_lvl = False\n        if t.exit_reason == "EOD":\n            xb = opt_bar(t.tradingsymbol, t.exit_ts)\n            if xb is not None and abs(xb["open"] - t.exit_price) > 0.011:\n                ok_lvl = False\n        if t.exit_reason == "XOVER":\n            xb = opt_bar(t.tradingsymbol, t.exit_ts)\n            if xb is not None and abs(xb["close"] - t.exit_price) > 0.011:\n                ok_lvl = False\n    check("every selection premium inside the band", ok_band)\n    check("every selection is the HIGHEST in-band premium of its side at that minute", ok_hi, bad[:3])\n    check("exit strictly after entry", ok_ord)\n    check("no entry at/after 14:30, no exit after 15:15, no overnight", ok_time)\n    check("close-fill entry price = the option\'s 1m close", ok_fill)\n    check("SL/TP/EOD/XOVER exit prices obey their conventions", ok_lvl)\n    srt = sorted(T, key=lambda x: x.entry_ts)\n    check("one position at a time", all(a.exit_ts <= b.entry_ts for a, b in zip(srt, srt[1:])))\n    reasons = {t.exit_reason for t in T}\n    check("several exit kinds exercised", len(reasons) >= 3, reasons)\n    check("expiry is the expected weekly", all(t.expiry == expected_expiry_for_day(IST_DATE(t.entry_ts)).isoformat() for t in T))\n    check("net = gross − charges on every trade", all(abs(t.net_pnl - (t.pnl - t.charges)) < 0.02 for t in T))\n    check("both option-trigger paths used (aligned at setup / after wait)",\n          dg.get("entries_aligned_at_setup", 0) > 0 and dg.get("entries_after_wait", 0) > 0, dg)\n\n    # next_open fill\n    r2 = run_emc_backtest(db_path=db, strategy_id="EMC_V1", underlying="NIFTY", date_from=date(2025, 1, 15),\n                          date_to=date(2025, 2, 28), config_override=dict(base))\n    ok = True\n    for t in r2["trades"]:\n        b = opt_bar(t.tradingsymbol, t.entry_ts)\n        if b is None or abs(b["open"] - t.entry_price) > 0.011:\n            ok = False\n    check("default next_open fill = the following minute\'s option open", ok and r2["trades"])\n\n    # caps\n    r3 = run_emc_backtest(db_path=db, strategy_id="EMC_V1", underlying="NIFTY", date_from=date(2025, 1, 15),\n                          date_to=date(2025, 2, 28), config_override=dict(base, max_trades_per_day=1))\n    per = {}\n    for t in r3["trades"]:\n        per[IST_DATE(t.entry_ts)] = per.get(IST_DATE(t.entry_ts), 0) + 1\n    check("max_trades_per_day = 1 honoured", per and max(per.values()) == 1)\n    r4 = run_emc_backtest(db_path=db, strategy_id="EMC_V1", underlying="NIFTY", date_from=date(2025, 1, 15),\n                          date_to=date(2025, 2, 28), config_override=dict(base, max_losses_per_day=1))\n    ok = True\n    by = {}\n    for t in sorted(r4["trades"], key=lambda x: x.entry_ts):\n        by.setdefault(IST_DATE(t.entry_ts), []).append(t)\n    for d, ts in by.items():\n        losers = [i for i, t in enumerate(ts) if t.net_pnl < 0]\n        if losers and losers[0] != len(ts) - 1:\n            ok = False\n    check("max_losses_per_day = 1: nothing is entered after the day\'s first loser", ok and by)\n    # cutoff / eod knobs\n    r5 = run_emc_backtest(db_path=db, strategy_id="EMC_V1", underlying="NIFTY", date_from=date(2025, 1, 15),\n                          date_to=date(2025, 2, 28), config_override=dict(base, entry_cutoff="12:00", eod_square_off="14:00"))\n    check("entry cutoff 12:00 / EOD 14:00 honoured",\n          r5["trades"] and all((t.entry_ts - ds_for(IST_DATE(t.entry_ts))) // 60 < 720 and\n                               (t.exit_ts - ds_for(IST_DATE(t.exit_ts))) // 60 <= 840 for t in r5["trades"]))\n    # trailing\n    r6 = run_emc_backtest(db_path=db, strategy_id="EMC_V1", underlying="NIFTY", date_from=date(2025, 1, 15),\n                          date_to=date(2025, 2, 28),\n                          config_override=dict(base, tp_pts=0, trail_on=True, trail_trigger_pts=8, trail_gap_pts=6))\n    check("trailing SL produces TSL exits", any(t.exit_reason == "TSL" for t in r6["trades"]))\n    # skip-expiry must not perturb the spot EMA on other days (R1)\n    r7 = run_emc_backtest(db_path=db, strategy_id="EMC_V1", underlying="NIFTY", date_from=date(2025, 1, 15),\n                          date_to=date(2025, 2, 28), config_override=dict(base, fill_mode="close", skip_expiry_day=True))\n    exp_days = {d for d in days if expected_expiry_for_day(d) == d}\n    keep = [(t.tradingsymbol, t.entry_ts, t.exit_ts) for t in T if IST_DATE(t.entry_ts) not in exp_days]\n    got = [(t.tradingsymbol, t.entry_ts, t.exit_ts) for t in r7["trades"]]\n    check("skip-expiry = same trades minus expiry days (spot EMA keeps advancing)", got == keep and exp_days,\n          (len(got), len(keep)))\n    # option bar_close mode never enters mid-bar (close fill, opt_tf 5)\n    r8 = run_emc_backtest(db_path=db, strategy_id="EMC_V1", underlying="NIFTY", date_from=date(2025, 1, 15),\n                          date_to=date(2025, 2, 28), config_override=dict(base, fill_mode="close", opt_check="bar_close"))\n    check("bar_close mode: entries only on 5m bar closes",\n          r8["trades"] and all(((t.entry_ts - ds_for(IST_DATE(t.entry_ts))) // 60 - O + 1) % 5 == 0 for t in r8["trades"]))\n    # lots / compounding hooks\n    r9 = run_emc_backtest(db_path=db, strategy_id="EMC_V1", underlying="NIFTY", date_from=date(2025, 1, 15),\n                          date_to=date(2025, 2, 28), config_override=dict(base, fill_mode="close", lots=3))\n    check("lots scale qty (3 × 65)", r9["trades"] and all(t.qty == 195 for t in r9["trades"]))\n    r10 = run_emc_backtest(db_path=db, strategy_id="EMC_V1", underlying="NIFTY", date_from=date(2025, 1, 15),\n                           date_to=date(2025, 2, 28), config_override=dict(base, fill_mode="close", dte_lot_mult="0:0"))\n    check("DTE × lots 0:0 skips expiry days", r10["summary"]["diag_emc"].get("dte_skipped_days", 0) >= 1\n          and not any(IST_DATE(t.entry_ts) in exp_days for t in r10["trades"]))\n\n    print("── FIX1: every entry is armed by a TRUE spot crossover (independent recompute) ──")\n    from app.backtest.emc.emc_v1_engine import ema_series as _es\n    from app.backtest.emc.backtest_emc_runner import _day_start_epoch as _dse\n    allspot = sorted({IST_DATE(r["ts"]) for r in con.execute(\n        "SELECT ts FROM backtest_candles_1m WHERE underlying=\'NIFTY\' AND instrument_type=\'SPOT\'")})\n    def xmap(from_day, warm=5):\n        prior = [d for d in allspot if d < from_day][-warm:]\n        seq = []\n        for d in prior + [d for d in allspot if d >= from_day]:\n            ds_ = _dse(d)\n            rows_ = [NS(ts=r["ts"], open=r["open"], high=r["high"], low=r["low"], close=r["close"]) for r in con.execute(\n                "SELECT ts, open, high, low, close FROM backtest_candles_1m WHERE underlying=\'NIFTY\' "\n                "AND instrument_type=\'SPOT\' AND ts>=? AND ts<? ORDER BY ts", (ds_, ds_ + 86400))]\n            for i_, b in enumerate(resample_session(rows_, day_start_epoch=ds_, tf_minutes=5)):\n                seq.append((d, b.end_min, b.close, i_ == 0))\n        f_, s_ = _es([x[2] for x in seq], 9), _es([x[2] for x in seq], 21)\n        out_ = {}\n        for i_ in range(1, len(seq)):\n            if None in (f_[i_ - 1], s_[i_ - 1], f_[i_], s_[i_]):\n                continue\n            if f_[i_ - 1] <= s_[i_ - 1] and f_[i_] > s_[i_]:\n                out_[(seq[i_][0], seq[i_][1])] = ("CE", seq[i_][3])\n            elif f_[i_ - 1] >= s_[i_ - 1] and f_[i_] < s_[i_]:\n                out_[(seq[i_][0], seq[i_][1])] = ("PE", seq[i_][3])\n        return out_\n    XM = xmap(date(2025, 1, 15))\n    def arm_of(t):\n        hh_, mm_ = t.condition.split("·arm")[1][:5].split(":")\n        return int(hh_) * 60 + int(mm_)\n    bad = [(t.tradingsymbol, t.condition) for t in T\n           if XM.get((IST_DATE(t.entry_ts), arm_of(t)), (None,))[0] != t.instrument_type\n           or arm_of(t) > (t.entry_ts - ds_for(IST_DATE(t.entry_ts))) // 60]\n    check(f"every trade\'s arm minute is a genuine EMA9/21 crossover of its side, at/before entry ({len(T)} trades)",\n          not bad and T, bad[:3])\n    # no other cross of either side between the arm and the entry (else the setup would have been replaced)\n    bad2 = []\n    for t in T:\n        d_, a_, e_ = IST_DATE(t.entry_ts), arm_of(t), (t.entry_ts - ds_for(IST_DATE(t.entry_ts))) // 60\n        if any(k[0] == d_ and a_ < k[1] < e_ for k in XM):\n            bad2.append(t.condition)\n    check("no spot cross between a trade\'s arming cross and its entry", not bad2, bad2[:3])\n    gap_trades = [t for t in T if XM.get((IST_DATE(t.entry_ts), arm_of(t)), (None, False))[1]]\n    rg = run_emc_backtest(db_path=db, strategy_id="EMC_V1", underlying="NIFTY", date_from=date(2025, 1, 15),\n                          date_to=date(2025, 2, 28), config_override=dict(base, fill_mode="close", first_candle_cross=False))\n    dgg = rg["summary"]["diag_emc"]\n    check(f"FIX1: gap crosses exist on the corpus and are counted ({dg.get(\'gap_crosses\')}; {len(gap_trades)} trades armed by one)",\n          dg.get("gap_crosses", 0) > 0 and gap_trades)\n    check("FIX1: first_candle_cross=False ignores every gap cross and arms nothing from them",\n          dgg.get("gap_crosses_ignored") == dgg.get("gap_crosses") > 0\n          and not [t for t in rg["trades"] if arm_of(t) == O + 4])\n    check("FIX1: trades not armed by a gap cross are unaffected on days without one",\n          [x.condition for x in rg["trades"] if all(not (k[0] == IST_DATE(x.entry_ts) and v[1]) for k, v in XM.items())]\n          == [x.condition for x in T if all(not (k[0] == IST_DATE(x.entry_ts) and v[1]) for k, v in XM.items())])\n    check("FIX1: default still counts gap crosses (existing runs reproduce)", DEFAULTS["first_candle_cross"] is True)\n\n    print("── BLACKOUT: runner ──")\n    rk = run_emc_backtest(db_path=db, strategy_id="EMC_V1", underlying="NIFTY", date_from=date(2025, 1, 15),\n                          date_to=date(2025, 2, 28), config_override=dict(base, fill_mode="close",\n                                                                           arm_skip_from="09:30", arm_skip_to="11:00"))\n    dk = rk["summary"]["diag_emc"]\n    check("blackout: no trade armed in [09:30, 11:00)", rk["trades"] and not [t for t in rk["trades"] if 570 <= arm_of(t) < 660])\n    check(f"blackout: crosses inside the window counted ({dk.get(\'sig_dropped_blackout\', 0)})", dk.get("sig_dropped_blackout", 0) > 0)\n    keep_days = {IST_DATE(t.entry_ts) for t in T if 570 <= arm_of(t) < 660}\n    check("blackout: days with no arm inside the window trade identically",\n          [t.condition for t in rk["trades"] if IST_DATE(t.entry_ts) not in keep_days]\n          == [t.condition for t in T if IST_DATE(t.entry_ts) not in keep_days])\n    rb0 = run_emc_backtest(db_path=db, strategy_id="EMC_V1", underlying="NIFTY", date_from=date(2025, 1, 15),\n                           date_to=date(2025, 2, 28), config_override=dict(base, fill_mode="close", arm_skip_from="", arm_skip_to=""))\n    check("blackout blank = off (identical to no key)", [t.condition for t in rb0["trades"]] == [t.condition for t in T])\n\n    print("── CARRY OVERNIGHT (EMC_CARRY_20261012, backtest only) ──")\n    CB = dict(base, fill_mode="close", sl_pts=0, tp_pts=0)     # no SL/TP → positions live to the cross / EOD\n    T_off = run_emc_backtest(db_path=db, strategy_id="EMC_V1", underlying="NIFTY", date_from=date(2025, 1, 15),\n                             date_to=date(2025, 2, 28), config_override=dict(CB))["trades"]\n    rc = run_emc_backtest(db_path=db, strategy_id="EMC_V1", underlying="NIFTY", date_from=date(2025, 1, 15),\n                          date_to=date(2025, 2, 28), config_override=dict(CB, carry_overnight=True))\n    TC = sorted(rc["trades"], key=lambda t: t.entry_ts)\n    dc = rc["summary"]["diag_emc"]\n    carried = [t for t in TC if "·carry" in t.condition]\n    check(f"carry: some positions are carried overnight ({len(carried)} trades, {dc.get(\'carry_nights\', 0)} nights)",\n          len(carried) >= 3 and dc.get("carry_nights", 0) >= len(carried) and dc.get("carried_trades") == len(carried)\n          and all(IST_DATE(t.exit_ts) > IST_DATE(t.entry_ts) for t in carried if t.exit_reason != "RUN_END"))\n    check("carry: tagged ·carryNn and counted in carried_pnl",\n          all("·carry" in t.condition for t in carried) and abs(dc["carried_pnl"] - sum(t.net_pnl for t in carried)) < 1)\n    check("carry: never held past the contract\'s expiry day, and never carried ON it",\n          all(IST_DATE(t.exit_ts).isoformat() <= t.expiry for t in TC)\n          and all(IST_DATE(t.entry_ts).isoformat() < t.expiry for t in carried))\n    exp_eod = [t for t in TC if t.exit_reason == "EOD" and IST_DATE(t.exit_ts).isoformat() == t.expiry]\n    check("carry: on expiry day the position exits at the square-off (EOD 15:15)",\n          exp_eod and all((t.exit_ts - ds_for(IST_DATE(t.exit_ts))) // 60 == 915 for t in exp_eod))\n    check("carry: non-expiry EOD exits disappear (they are carried instead)",\n          all(IST_DATE(t.exit_ts).isoformat() == t.expiry for t in TC if t.exit_reason == "EOD"))\n    check("carry: one position at a time across days", all(a.exit_ts <= b.entry_ts for a, b in zip(TC, TC[1:])))\n    gap_ok, gap_n = True, 0\n    gap_runs = [t for sl_, tp_ in ((15, 0), (20, 60), (0, 30)) for t in run_emc_backtest(\n        db_path=db, strategy_id="EMC_V1", underlying="NIFTY", date_from=date(2025, 1, 15), date_to=date(2025, 3, 31),\n        config_override=dict(CB, sl_pts=sl_, tp_pts=tp_, carry_overnight=True))["trades"] if "·carry" in t.condition]\n    for t in gap_runs:\n        if t.exit_reason in ("SL", "TP") and (t.exit_ts - ds_for(IST_DATE(t.exit_ts))) // 60 == 555:\n            b = opt_bar(t.tradingsymbol, t.exit_ts)\n            gap_n += 1\n            lvl = t.sl if t.exit_reason == "SL" else t.tp\n            through = (b["open"] <= lvl) if t.exit_reason == "SL" else (b["open"] >= lvl)\n            if through and abs(t.exit_price - b["open"]) > 0.011:\n                gap_ok = False\n            if not through and abs(t.exit_price - lvl) > 0.011:\n                gap_ok = False\n    check(f"carry: next-morning SL/TP books the open when gapped through, else the level ({gap_n} cases)", gap_ok and gap_n >= 3)\n    cut = ds_for(IST_DATE(carried[0].entry_ts)) + 915 * 60          # the first square-off that carries\n    pre_on = [(t.condition, t.exit_ts, t.exit_price) for t in TC if t.exit_ts < cut]\n    pre_off = [(t.condition, t.exit_ts, t.exit_price) for t in T_off if t.exit_ts < cut]\n    check(f"carry: identical to intraday until the first carried night ({len(pre_on)} trades)", pre_on == pre_off)\n    # qty of a carried trade is its ENTRY day\'s qty (DTE × lots scales other days)\n    rq = run_emc_backtest(db_path=db, strategy_id="EMC_V1", underlying="NIFTY", date_from=date(2025, 1, 15),\n                          date_to=date(2025, 2, 28), config_override=dict(CB, carry_overnight=True, dte_lot_mult="1:3"))\n    from app.backtest.engine.dte_lots import dte_for_day\n    from app.backtest.repo.trading_calendar import trading_dates\n    cal = trading_dates("NIFTY", db)\n    q_ok, q_n = True, 0\n    for t in rq["trades"]:\n        dte = dte_for_day(cal, IST_DATE(t.entry_ts).isoformat(), expected_expiry_for_day(IST_DATE(t.entry_ts)).isoformat())\n        want_q = 195 if dte == 1 else 65\n        q_n += IST_DATE(t.exit_ts) > IST_DATE(t.entry_ts)\n        if t.qty != want_q:\n            q_ok = False\n    check(f"carry: a carried trade keeps its entry day\'s qty (DTE × lots 1:3; {q_n} carried)", q_ok and q_n)\n    # sessions skipped for entries still manage the carry\n    rs = run_emc_backtest(db_path=db, strategy_id="EMC_V1", underlying="NIFTY", date_from=date(2025, 1, 15),\n                          date_to=date(2025, 2, 28), config_override=dict(CB, carry_overnight=True, skip_expiry_day=True))\n    ds_ = rs["summary"]["diag_emc"]\n    exp_days = {d for d in days if expected_expiry_for_day(d) == d}\n    managed = [t for t in rs["trades"] if IST_DATE(t.exit_ts) in exp_days and IST_DATE(t.entry_ts) not in exp_days]\n    check("carry + skip expiry day: no entry on expiry days, but a carried position is managed there",\n          not any(IST_DATE(t.entry_ts) in exp_days for t in rs["trades"]) and managed\n          and ds_.get("carry_managed_skip_days", 0) > 0, (len(managed), ds_.get("carry_managed_skip_days")))\n    # open at the end of the run → RUN_END\n    found = None\n    for t in carried:\n        d_end = IST_DATE(t.entry_ts)\n        if d_end.weekday() < 4 and IST_DATE(t.exit_ts) > d_end:\n            found = d_end; break\n    if found:\n        rr2 = run_emc_backtest(db_path=db, strategy_id="EMC_V1", underlying="NIFTY", date_from=date(2025, 1, 15),\n                               date_to=found, config_override=dict(CB, carry_overnight=True))\n        last = sorted(rr2["trades"], key=lambda t: t.exit_ts)[-1]\n        check("carry: a position open when the run ends is closed at its last mark (RUN_END)",\n              last.exit_reason == "RUN_END" and rr2["summary"]["diag_emc"]["run_end_exits"] == 1)\n    from app.engine.emc.emc_live_core import live_params\n    check("carry is refused by the paper/live engine (backtest-only)",\n          live_params(dict(DEFAULTS, carry_overnight=True))[2] is not None and live_params(dict(DEFAULTS))[2] is None)\n\n    print("── SELL + wing (EMC_SELL_20261012, backtest only) ──")\n    SB = dict(base, fill_mode="close", leg_action="SELL")\n    r_s = run_emc_backtest(db_path=db, strategy_id="EMC_V1", underlying="NIFTY", date_from=date(2025, 1, 15),\n                           date_to=date(2025, 2, 28), config_override=dict(SB))\n    TS = r_s["trades"]\n    check(f"SELL: trades are SELL rows ({len(TS)})", len(TS) >= 10 and all(t.direction == "SELL" for t in TS))\n    ok_side = all(XM.get((IST_DATE(t.entry_ts), arm_of(t)), ("?",))[0] == ("CE" if t.instrument_type == "PE" else "PE")\n                  for t in TS)\n    check("SELL: every short is the OPPOSITE type of its arming cross (up → PE, down → CE)", ok_side)\n    from app.backtest.charges.charges_model import charges_for_short_trade, charges_for_long_trade\n    ok_pnl = all(abs(t.pnl - (t.entry_price - t.exit_price) * t.qty) < 0.6 and\n                 abs(t.charges - charges_for_short_trade(entry_price=t.entry_price, exit_price=t.exit_price,\n                                                         qty=t.qty).total_charges) < 0.6 for t in TS)\n    check("SELL naked: gross = (entry − exit) × qty, short-side charges (STT on the sale)", ok_pnl)\n    check("SELL: SL above / TP below every entry", all(t.sl > t.entry_price and t.tp < t.entry_price for t in TS))\n    ok_lv = all((t.exit_reason != "SL" or t.exit_price >= t.sl - 0.011) and (t.exit_reason != "TP" or t.exit_price <= t.tp + 0.011)\n                for t in TS)\n    check("SELL: stop fills at/above its level, target at/below", ok_lv)\n    r_h = run_emc_backtest(db_path=db, strategy_id="EMC_V1", underlying="NIFTY", date_from=date(2025, 1, 15),\n                           date_to=date(2025, 2, 28), config_override=dict(SB, hedge_enabled=True, hedge_max_premium=20,\n                                                                            hedge_synth_enabled=False))\n    TH, dh = r_h["trades"], r_h["summary"]["diag_emc"]\n    check(f"wing: every hedged short carries a wing ({len(TH)} trades, {dh[\'hedge_real\']} real)",\n          TH and all(t.wing_symbol and 0 < t.wing_entry <= 20 for t in TH) and dh["hedge_real"] == len(TH))\n    ok_w = ok_dear = True\n    for t in TH:\n        if t.wing_symbol[-2:] != t.instrument_type:\n            ok_w = False\n        r_ = con.execute("SELECT expiry FROM backtest_candles_1m WHERE tradingsymbol=? LIMIT 1", (t.wing_symbol,)).fetchone()\n        if r_ is None or r_["expiry"] != t.expiry:\n            ok_w = False\n        px_at = con.execute("SELECT close FROM backtest_candles_1m WHERE tradingsymbol=? AND ts<=? AND ts>=? ORDER BY ts DESC LIMIT 1",\n                            (t.wing_symbol, t.entry_ts, ds_for(IST_DATE(t.entry_ts)))).fetchone()\n        if px_at is None or abs(px_at["close"] - t.wing_entry) > 0.011:\n            ok_w = False\n        for (sym2,) in con.execute("SELECT DISTINCT tradingsymbol FROM backtest_candles_1m WHERE expiry=? AND instrument_type=? "\n                                   "AND ts>=? AND ts<?", (t.expiry, t.instrument_type, ds_for(IST_DATE(t.entry_ts)),\n                                                          ds_for(IST_DATE(t.entry_ts)) + 86400)):\n            if sym2 in (t.tradingsymbol, t.wing_symbol):\n                continue\n            q2 = con.execute("SELECT close FROM backtest_candles_1m WHERE tradingsymbol=? AND ts<=? AND ts>=? ORDER BY ts DESC LIMIT 1",\n                             (sym2, t.entry_ts, ds_for(IST_DATE(t.entry_ts)))).fetchone()\n            if q2 is not None and t.wing_entry < q2["close"] <= 20:\n                ok_dear = False\n    check("wing: same type & expiry as the short, priced at its last print at/before the fill", ok_w)\n    check("wing: the DEAREST real contract at or under the cap (VET\'s rule)", ok_dear)\n    ok_pair = all(abs(t.pnl - ((t.entry_price - t.exit_price) + (t.wing_exit - t.wing_entry)) * t.qty) < 0.6 for t in TH)\n    check("wing: the row\'s P&L is the PAIR (short + wing), one row per position", ok_pair)\n    check("wing: diag hedge_cost_total = Σ wing net", abs(dh["hedge_cost_total"] - sum(\n        (t.wing_exit - t.wing_entry) * t.qty - charges_for_long_trade(entry_price=t.wing_entry, exit_price=t.wing_exit,\n                                                                      qty=t.qty).total_charges for t in TH)) < 1)\n    r_n = run_emc_backtest(db_path=db, strategy_id="EMC_V1", underlying="NIFTY", date_from=date(2025, 1, 15),\n                           date_to=date(2025, 2, 28), config_override=dict(SB, hedge_enabled=True, hedge_max_premium=0.6,\n                                                                            hedge_synth_enabled=False))\n    dn = r_n["summary"]["diag_emc"]\n    check(f"no wing → no trade (fail-closed; {dn[\'no_hedge_entries\']} entries refused)",\n          dn["no_hedge_entries"] > 0 and all(t.wing_symbol for t in r_n["trades"]) and len(r_n["trades"]) < len(TS))\n    r_y = run_emc_backtest(db_path=db, strategy_id="EMC_V1", underlying="NIFTY", date_from=date(2025, 1, 15),\n                           date_to=date(2025, 2, 28), config_override=dict(SB, hedge_enabled=True, hedge_max_premium=2))\n    dy = r_y["summary"]["diag_emc"]\n    check(f"wing: model-priced fallback when nothing real fits the cap ({dy[\'hedge_synth\']} synthetic), rows flagged synthetic",\n          dy["hedge_synth"] > 0 and sum(1 for t in r_y["trades"] if t.synthetic) == dy["hedge_synth_exits"] > 0)\n    r_c = run_emc_backtest(db_path=db, strategy_id="EMC_V1", underlying="NIFTY", date_from=date(2025, 1, 15),\n                           date_to=date(2025, 2, 28), config_override=dict(SB, sl_pts=0, tp_pts=0, carry_overnight=True,\n                                                                            hedge_enabled=True, hedge_max_premium=20,\n                                                                            hedge_synth_enabled=False))\n    cs = [t for t in r_c["trades"] if "·carry" in t.condition]\n    check(f"SELL + carry: shorts carry with their wing ({len(cs)} carried)",\n          cs and all(t.wing_symbol and t.direction == "SELL" for t in cs)\n          and all(abs(t.pnl - ((t.entry_price - t.exit_price) + (t.wing_exit - t.wing_entry)) * t.qty) < 0.6 for t in cs))\n    for nm, over in (("SELL TP reaching the band bottom", dict(SB, tp_pts=60)),\n                     ("hedge on a BUY", dict(base, hedge_enabled=True)),\n                     ("hedge cap reaching the sold band", dict(SB, hedge_enabled=True, hedge_max_premium=60))):\n        r_ = run_emc_backtest(db_path=db, strategy_id="EMC_V1", underlying="NIFTY", date_from=date(2025, 2, 3),\n                              date_to=date(2025, 2, 4), config_override=over)\n        check(f"abort: {nm}", r_.get("aborted") and not r_["trades"], r_.get("reason"))\n    from app.engine.emc.emc_live_core import live_params as _lp\n    check("SELL / hedge refused by the paper/live engine (backtest-only)",\n          _lp(dict(DEFAULTS, leg_action="SELL"))[2] is not None and _lp(dict(DEFAULTS, hedge_enabled=True))[2] is not None)\n\n    print("── runner: config guards (abort, never run) ──")\n    for name, over in (("fast >= slow", {"ema_fast": 21, "ema_slow": 9}),\n                       ("band inverted", {"sel_prem_min": 200, "sel_prem_max": 150}),\n                       ("cutoff after eod", {"entry_cutoff": "15:20", "eod_square_off": "15:15"}),\n                       ("eod after 15:29", {"eod_square_off": "15:40"}),\n                       ("bad time text", {"entry_cutoff": "2pm"}),\n                       ("sl looks like a %", {"sl_pts": 250}),\n                       ("trail without gap", {"trail_on": True, "trail_gap_pts": 0}),\n                       ("tf 90", {"spot_tf": 90}),\n                       ("blackout from only", {"arm_skip_from": "09:30"}),\n                       ("blackout inverted", {"arm_skip_from": "10:00", "arm_skip_to": "09:30"}),\n                       ("blackout bad text", {"arm_skip_from": "9.30", "arm_skip_to": "10:00"})):\n        r = run_emc_backtest(db_path=db, strategy_id="EMC_V1", underlying="NIFTY", date_from=date(2025, 2, 3),\n                             date_to=date(2025, 2, 4), config_override=over)\n        check(f"abort: {name}", r.get("aborted") and not r["trades"], r.get("reason"))\n    r = run_emc_backtest(db_path=db, strategy_id="EMC_V1", underlying="NIFTY", date_from=date(2025, 2, 3),\n                         date_to=date(2025, 2, 28), config_override=base, cancel_cb=lambda: True)\n    check("cancel_cb stops before trading", not r["trades"])\n    cfg = _merge_cfg({"trail_on": "false", "direction": "x", "opt_check": "BAR_CLOSE"})\n    check("merge: string booleans / unknown enums normalised", cfg["trail_on"] is False and cfg["direction"] == "BOTH"\n          and cfg["opt_check"] == "bar_close")\n    check("defaults are the spec (5m, EMA 9/21, ₹150–200 highest, cutoff 14:30, EOD 15:15)",\n          DEFAULTS["spot_tf"] == 5 and DEFAULTS["opt_tf"] == 5 and DEFAULTS["ema_fast"] == 9 and DEFAULTS["ema_slow"] == 21\n          and DEFAULTS["sel_prem_min"] == 150 and DEFAULTS["sel_prem_max"] == 200 and DEFAULTS["sel_pick"] == "highest"\n          and DEFAULTS["entry_cutoff"] == "14:30" and DEFAULTS["eod_square_off"] == "15:15")\n    print("── replay: persisted run → Trade Replay (EMC overlay) ──")\n    from pathlib import Path\n    import app.backtest.repo.backtest_repo as BR\n    import app.backtest.replay.replay_core as RC\n    import app.backtest.replay.overlays as OV\n    BR._db_path = lambda: Path(db)\n    RC.runs_db_path = lambda: db\n    check("EMC_V1 registered in the replay overlay registry", "EMC_V1" in OV.REGISTRY)\n    rr = run_emc_backtest(db_path=db, strategy_id="EMC_V1", underlying="NIFTY", date_from=date(2025, 1, 15),\n                          date_to=date(2025, 2, 28), config_override=dict(base, fill_mode="close"))\n    rr["meta"] = {"strategy_id": "EMC_V1", "underlying": "NIFTY", "date_from": "2025-01-15", "date_to": "2025-02-28"}\n    rid = BR.persist_run(rr)\n    rows = [dict(r) for r in con.execute("SELECT * FROM backtest_trades WHERE run_id=? ORDER BY entry_ts, id", (rid,))]\n    check("persist_run stores every EMC trade with its condition", len(rows) == len(rr["trades"]) and\n          all(r.get("condition", "").startswith("EMC·") for r in rows))\n    ok_tier = ok_x = ok_opt = ok_arm = ok_win = ok_frame = True\n    n = 0\n    for r in rows[:12]:\n        out = RC.build_replay(rid, int(r["id"]))\n        if not out.get("ok", True) or "spot" not in out:\n            ok_tier = False\n            continue\n        n += 1\n        par = (out.get("parity") or {}).get("tier") or (out.get("meta") or {}).get("parity", {}).get("tier")\n        sp = {o.get("id"): o for o in out["spot"]["overlays"]}\n        if not (sp.get("ema_fast", {}).get("points") and sp.get("ema_slow", {}).get("points")):\n            ok_tier = False\n        # the arming cross: selection minute = entry − wait (close fill); its spot bar starts 4 min earlier\n        cond = r["condition"]\n        hh, mm = cond.split("·arm")[1][:5].split(":")\n        d_ = IST_DATE(int(r["entry_ts"]))\n        bar_ts = ds_for(d_) + (int(hh) * 60 + int(mm) - 4) * 60\n        dots = [p for p in sp.get("crosses", {}).get("points", []) if p[0] == bar_ts]\n        if not dots or (("▲" in dots[0][2]) != (r["instrument_type"] == "CE")):\n            ok_x = False\n        armed = sp.get("armed", {}).get("points", [])\n        if not armed or armed[0][0] != bar_ts or f"ARMED {r[\'instrument_type\']}" not in armed[0][2]:\n            ok_arm = False\n        if len(out["window"]["days"]) != 2 or out["window"]["days"][1] != d_.isoformat():\n            ok_win = False\n        if out["window"].get("frame_from_ts") != bar_ts:\n            ok_frame = False\n        po = out["premium"]["overlays"].get(r["tradingsymbol"], [])\n        if not any(o.get("id") == "opt_ema_slow" and o.get("points") for o in po):\n            ok_opt = False\n    check(f"replay builds with spot EMA lines ({n} trades)", ok_tier and n)\n    check("every replayed entry\'s arming spot cross is drawn at its bar, same direction", ok_x)\n    check("the traded option\'s own EMA pair is drawn on the premium pane", ok_opt)\n    check("FIX1: the ARMED marker sits on the arming spot candle", ok_arm)\n    check("FIX1: the previous session is drawn before the entry day", ok_win)\n    check("FIX1: \'Trade\' framing starts at the arming candle", ok_frame)\n    con.close()\n\nif FAILS:\n    print(f"\\n{len(FAILS)} FAILURES: {FAILS}")\n    sys.exit(1)\nprint(f"\\nALL {NPASS[0]} EMC CHECKS PASSED")\n')

REPLACE['backend/app/engine/emc/emc_live_core.py'] = ('06e40cf765f013c8709946a7e0fa2a15077c7c534cf98400b823ff4a6a7e0c8a', '# backend/app/engine/emc/emc_live_core.py\n#\n# ── EMC_V1 LIVE CORE ── PURE (no broker / DB imports; unit-tested)\n# Fence: EMC_V1_LIVE_20261011\n# ============================================================================\n# THE PARITY DESIGN (VET / PST doctrine): this file holds NO decision logic.\n# Decisions are app.backtest.emc.emc_v1_engine.EmcDayCore — the very object\n# the backtest\'s simulate_day drives — and every indicator is re-computed by\n# the backtest\'s own functions over the growing day prefix:\n#\n#   * LiveSpotCrosses — spot 1m candles (prior sessions + today, FROZEN once\n#     accepted) → resample_session → spot_crosses on a FRESH EmaPair each\n#     time. Same arithmetic, same continuity, same first-candle (gap) rule\n#     and the same R1 "advance on every session" warm-up as the runner.\n#     A PrefixGuard freezes the strategy if any already-reported cross is\n#     ever restated (a corpus gap or duplicated minute would do that).\n#   * LiveOptionTrack — the selected contract\'s prior-session bars + today\'s\n#     frozen 1m candles → a FRESH OptionEmaTrack evaluated at minute k.\n#     OptionEmaTrack is causal (proven minute-by-minute against a brute-force\n#     recompute in test_emc_runner_sim), so prefix data gives the backtest\'s\n#     value exactly.\n#   * live_params(cfg) — the runner\'s own _merge_cfg + validate + DayParams\n#     build: one config vocabulary, no second parser.\n#\n# WHAT THIS FILE REFUSES (fail closed, by live_problems):\n#   * trail_on — the sealed config has it OFF; a live trailing stop would\n#     need its own parity study (peak through the previous minute).\n#   * fill_mode "close" — a live order cannot fill at a past close; live is\n#     inherently the "next_open" model the seal was tested with.\n# ============================================================================\n\nfrom __future__ import annotations\n\nfrom typing import Dict, List, Optional, Sequence, Tuple\n\ntry:\n    from app.backtest.emc.emc_v1_engine import (EmcBar, EmaPair, OptionEmaTrack, DayParams,\n                                                resample_session, spot_crosses, SESSION_OPEN_MIN)\nexcept ImportError:                                        # standalone tests\n    from emc_v1_engine import (EmcBar, EmaPair, OptionEmaTrack, DayParams,  # type: ignore\n                               resample_session, spot_crosses, SESSION_OPEN_MIN)\n\nIST_OFFSET = 5 * 3600 + 30 * 60\n\n\ndef day_start_epoch_of(ts: int) -> int:\n    """00:00 IST of the day containing ts (the corpus / runner day anchor)."""\n    return ((int(ts) + IST_OFFSET) // 86400) * 86400 - IST_OFFSET\n\n\ndef minute_of(ts: int) -> int:\n    return ((int(ts) + IST_OFFSET) % 86400) // 60\n\n\ndef _bar(c) -> EmcBar:\n    if isinstance(c, EmcBar):\n        return c\n    return EmcBar(int(c["ts"]), float(c["open"]), float(c["high"]), float(c["low"]), float(c["close"]))\n\n\ndef _group_sessions(candles: Sequence) -> List[Tuple[int, List[EmcBar]]]:\n    by: Dict[int, List[EmcBar]] = {}\n    for c in candles:\n        b = _bar(c)\n        by.setdefault(day_start_epoch_of(b.ts), []).append(b)\n    return [(ds, sorted(v, key=lambda x: x.ts)) for ds, v in sorted(by.items())]\n\n\n# ─────────────────────────────────────────────────────────────────────────\n#  config — the runner\'s vocabulary, verbatim\n# ─────────────────────────────────────────────────────────────────────────\ndef live_params(cfg: dict) -> Tuple[Optional[DayParams], dict, Optional[str]]:\n    """→ (DayParams | None, merged cfg, problem | None). Uses the backtest\n    runner\'s _merge_cfg / validate / _hhmm so the live engine reads a config\n    exactly as a backtest run would."""\n    from app.backtest.emc.backtest_emc_runner import _merge_cfg, validate, _hhmm\n    m = _merge_cfg(cfg or {})\n    bad = validate(m) or live_problems(m)\n    if bad:\n        return None, m, bad\n    p = DayParams(\n        sel_lo=m["sel_prem_min"], sel_hi=m["sel_prem_max"], sel_pick=m["sel_pick"],\n        direction=m["direction"], intrabar=m["opt_check"] == "intrabar",\n        opt_min_bars=m["opt_min_bars"] or m["ema_slow"], fill=m["fill_mode"],\n        sl_pts=m["sl_pts"], tp_pts=m["tp_pts"], trail_on=m["trail_on"],\n        trail_trigger=m["trail_trigger_pts"], trail_gap=m["trail_gap_pts"], xover_exit=m["xover_exit"],\n        block_min=_hhmm(m["entry_cutoff"], 14 * 60 + 30), eod_min=_hhmm(m["eod_square_off"], 15 * 60 + 15),\n        max_trades=m["max_trades_per_day"], max_losses=m["max_losses_per_day"],\n        skip_from=_hhmm(m["arm_skip_from"], -1) if m.get("arm_skip_from") else -1,\n        skip_to=_hhmm(m["arm_skip_to"], -1) if m.get("arm_skip_to") else -1)\n    return p, m, None\n\n\ndef live_problems(m: dict) -> Optional[str]:\n    if m.get("trail_on"):\n        return "trailing SL is not supported in paper/live (sealed config has it OFF) — refusing to trade"\n    if m.get("fill_mode") == "close":\n        return "fill_mode \'close\' cannot be executed live (orders fill after the decision) — set next_open"\n    if m.get("leg_action", "BUY") != "BUY" or m.get("hedge_enabled"):   # ── EMC_SELL_20261012 ──\n        return "leg_action SELL / hedge wing are backtest-only for now — refusing to trade (set BUY)"\n    if m.get("carry_overnight"):                   # ── EMC_CARRY_20261012 ──\n        return "carry_overnight is backtest-only for now — refusing to trade (set it back to OFF)"\n    if str(m.get("underlying", "NIFTY")).upper() != "NIFTY":\n        return "EMC_V1 paper/live is NIFTY-only"\n    return None\n\n\n# ─────────────────────────────────────────────────────────────────────────\n#  prefix guard\n# ─────────────────────────────────────────────────────────────────────────\nclass CrossGuard:\n    """A cross reported for a completed spot bar must never change or vanish\n    as later candles arrive. On violation: FREEZE (no new setups; an open\n    position is still managed to its exit)."""\n\n    def __init__(self) -> None:\n        self.seen: Dict[int, int] = {}\n        self.frozen = False\n        self.reason: Optional[str] = None\n\n    def check(self, crosses: Dict[int, int], upto_min: int) -> bool:\n        if self.frozen:\n            return False\n        for m, x in self.seen.items():\n            if m <= upto_min and crosses.get(m, 0) != x:\n                self.frozen = True\n                self.reason = f"spot cross at minute {m} restated {x} → {crosses.get(m, 0)} — prefix instability"\n                return False\n        for m, x in crosses.items():\n            if m <= upto_min:\n                self.seen[m] = x\n        return True\n\n\n# ─────────────────────────────────────────────────────────────────────────\n#  spot crosses over the growing prefix\n# ─────────────────────────────────────────────────────────────────────────\nclass LiveSpotCrosses:\n    def __init__(self, *, fast: int, slow: int, tf: int, warm_sessions_1m: Sequence[Sequence],\n                 need_sessions: int, first_candle_cross: bool = True):\n        self.fast, self.slow, self.tf = int(fast), int(slow), int(tf)\n        self.first_candle_cross = bool(first_candle_cross)\n        self.need = int(need_sessions)\n        warm: List[EmcBar] = []\n        for sess in warm_sessions_1m:\n            for b in sess:\n                warm.append(_bar(b))\n        self.warm_sessions = _group_sessions(warm)\n        self.today: List[EmcBar] = []\n        self.ds: Optional[int] = None\n        self.guard = CrossGuard()\n        self.crosses: Dict[int, int] = {}\n        self.gap_cross_min: Optional[int] = None\n        self.last_vals: Tuple[Optional[float], Optional[float]] = (None, None)\n\n    def warmup_ok(self) -> bool:\n        return len(self.warm_sessions) >= self.need\n\n    def add(self, candle) -> bool:\n        """Freeze one COMPLETED 1m spot candle of today. Out-of-order or\n        duplicate minutes are ignored (False)."""\n        b = _bar(candle)\n        if self.ds is None:\n            self.ds = day_start_epoch_of(b.ts)\n        if day_start_epoch_of(b.ts) != self.ds:\n            return False\n        if self.today and b.ts <= self.today[-1].ts:\n            return False\n        if minute_of(b.ts) < SESSION_OPEN_MIN:\n            return False\n        self.today.append(b)\n        return True\n\n    def last_minute(self) -> Optional[int]:\n        return minute_of(self.today[-1].ts) if self.today else None\n\n    def recompute(self) -> Dict[int, int]:\n        """Crosses of today\'s COMPLETED spot bars, keyed by bar end minute —\n        the runner\'s R1 / R6 computation on the current prefix."""\n        if self.ds is None:\n            return {}\n        pair = EmaPair(self.fast, self.slow)\n        for wds, wb in self.warm_sessions:\n            for b in resample_session(wb, day_start_epoch=wds, tf_minutes=self.tf):\n                pair.update(b.close)\n        upto = self.last_minute() or -1\n        bars = [b for b in resample_session(self.today, day_start_epoch=self.ds, tf_minutes=self.tf)\n                if b.end_min <= upto]                     # completed buckets only\n        xs = spot_crosses(bars, pair)\n        self.last_vals = pair.values\n        self.gap_cross_min = None\n        if bars and (bars[0].ts - self.ds) // 60 == SESSION_OPEN_MIN and bars[0].end_min in xs:\n            self.gap_cross_min = bars[0].end_min\n            if not self.first_candle_cross:\n                del xs[bars[0].end_min]\n        if not self.guard.check(xs, upto):\n            return self.crosses\n        self.crosses = xs\n        return xs\n\n\n# ─────────────────────────────────────────────────────────────────────────\n#  the selected option\'s EMA over the growing prefix\n# ─────────────────────────────────────────────────────────────────────────\nclass LiveOptionTrack:\n    """Drop-in for the runner\'s OptionEmaTrack (same .at(k, intrabar))."""\n\n    def __init__(self, *, fast: int, slow: int, tf: int, ds: int, warm_bars: Sequence[EmcBar]):\n        self.fast, self.slow, self.tf, self.ds = int(fast), int(slow), int(tf), int(ds)\n        self.warm_bars = list(warm_bars)\n        self.today: List[EmcBar] = []\n\n    def add(self, candle) -> bool:\n        b = _bar(candle)\n        if day_start_epoch_of(b.ts) != self.ds:\n            return False\n        if self.today and b.ts <= self.today[-1].ts:\n            return False\n        self.today.append(b)\n        return True\n\n    def at(self, k: int, intrabar: bool = True):\n        known = [b for b in self.today if (b.ts - self.ds) // 60 <= k]\n        tr = OptionEmaTrack(fast=self.fast, slow=self.slow, tf=self.tf, ds=self.ds,\n                            warm_bars=self.warm_bars, today_1m=known)\n        return tr.at(k, intrabar)\n\n\ndef option_warm_from_sessions(sessions: Sequence[Tuple[int, Sequence]], tf: int) -> List[EmcBar]:\n    """The runner\'s option_warm_bars on already-fetched prior sessions\n    [(day_start, candles)], oldest first."""\n    out: List[EmcBar] = []\n    for ds, cs in sessions:\n        out.extend(resample_session([_bar(c) for c in cs], day_start_epoch=ds, tf_minutes=tf))\n    return out\n')

